// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Divan edebiyatı nazım biçimleri ve şairleri ayrıntılı (orta).
const ozLiterature6Orta = <(String, String, List<String>, String)>[
  ('Her beyti dört parçaya bölünen, ilk üç parçası kendi arasında, dördüncü parçası gazelin ana kafiyesiyle kafiyelenen gazel türü hangisidir?', 'Musammat gazel', ['Yek-ahenk gazel', 'Mülemma gazel', 'Mütekerrir gazel'], 'Musammat gazelde dizeler iç kafiyelerle bölünür; böylece beyit dörtlük gibi okunabilir ve ahenk güçlenir.'),
  ('Gazellerde dizelerin bir kısmının Türkçe, bir kısmının Arapça ya da Farsça yazılmasıyla oluşan şiirlere ne ad verilir?', 'Mülemma', ['Musammat', 'Müzeyyel', 'Mürettep'], 'Birden çok dille yazılmış dizeleri bir arada bulunduran şiire mülemma denir; Divan şairleri dil ustalıklarını bu yolla gösterirdi.'),
  ('Bir divanda gazeller redif harflerine göre sıralanır. Elifbanın her harfiyle biten en az bir gazeli bulunan divana ne ad verilir?', 'Mürettep divan', ['Mülemma divan', 'Müntehab divan', 'Kâmil (eksiksiz) külliyat'], 'Her harften gazel içeren, düzenli divana mürettep divan denir. Bu, şairin kafiye ve redif ustalığını da gösterir.'),
  ('Divan şiirinde aynı ölçü, kafiye ve rediften oluşan gazelin bölünmeden kasidenin içine yerleştirilmesine tegazzül denir. Bu bilgi gazel ile kaside arasındaki hangi ortak özelliğe dayanır?', 'İkisinin de aa ba ca kafiye düzeniyle yazılması', ['İkisinin de bentlerden oluşması', 'İkisinin de mesnevi gibi her beytin kendi içinde kafiyelenmesi', 'İkisinin de hece ölçüsüyle yazılması'], 'Gazel ile kasidenin kafiye düzeni aynıdır; bu yüzden bir gazel kasidenin içine aynı vezin ve kafiyede yerleştirilebilir.'),
  ('Türk musikisinde \'gazel\' adı, şiir türünün yanında hangi icra biçimini de anlatır?', 'Ölçüsüz, doğaçlama sözlü bir okuyuşu', ['Usulü belli bir saz peşrevini', 'Mehter takımının yürüyüş marşını', 'Tekkelerde topluca söylenen bir ilahiyi'], 'Musikide gazel, bir şiirin usulsüz ve doğaçlama olarak makam içinde okunmasıdır; bunu icra edene gazelhan denir.'),
  ('Bir kasidenin ortasında, şairin aynı ölçüde yeni bir matla beytiyle şiire adeta yeniden başlamasına ne ad verilir?', 'Tecdid-i matla', ['Hüsn-i matla', 'Tegazzül', 'Girizgâh beyti'], 'Kasidenin içinde iki dizesi kafiyeli yeni bir matla ile bölüm açılmasına tecdid-i matla denir.'),
  ('Kasidenin dua bölümünde şairler övdükleri kişinin ömrünün ve devletinin uzun sürmesini hangi tür bir anlatımla dilerler?', 'Bir doğa olayının sürmesine bağlayarak sürekli olmasını dilerler', ['Övülen kişiyi yererek uyarırlar', 'Kendi şiirlerini överek bitirirler', 'Gazel kafiyesini bırakıp düzyazıya geçerek övülen kişiye mektup yazarlar'], 'Dua bölümünde genellikle \'dünya durdukça, bahar geldikçe\' gibi bir koşula bağlanarak övülen kişinin devletinin sürmesi dilenir.'),
  ('Kasidenin nesib bölümüne \'teşbib\' de denmesinin nedeni hangisidir?', 'Bu bölümde genellikle güzellik, gençlik ve doğa tasvirlerinin yapılması', ['Bu bölümün yalnız benzetmesiz yazılması', 'Bu bölümün şairin adını taşıması', 'Bu bölümde yalnız dua ve ölüm sonrasına ilişkin dilekler bulunması gerekmesi'], 'Teşbib, gençliği ve güzelliği anma, tasvir etme anlamı taşır; kasidenin tasvirli girişine bu adla da işaret edilir.'),
  ('Mesnevilerin giriş bölümünde, eserin neden ve kimin isteğiyle yazıldığının anlatıldığı kısma ne ad verilir?', 'Sebeb-i telif', ['Hatime', 'Girizgâh', 'Çehar-yâr-ı güzîn'], 'Sebeb-i telif \'yazılış nedeni\' demektir; şair burada eseri neden kaleme aldığını açıklar.'),
  ('Mesnevilerin girişinde, Hz. Muhammed\'in göğe yükselişini anlatan bölüme ne ad verilir?', 'Miraciye', ['Münacat', 'Tevhid', 'Sebeb-i telif'], 'Miraç olayını anlatan bölüm ya da şiire miraciye denir; mesnevilerin giriş kısmında naattan sonra sık yer alır.'),
  ('Mesnevilerin uzun olmasına karşın aruzun daha çok kısa kalıplarıyla yazılmasının en makul nedeni hangisidir?', 'Binlerce beyitlik anlatımda akıcılığı korumak', ['Kısa kalıpların bestelenmeye elverişli olması', 'Uzun kalıpların yalnız tuyuğda kullanılabilmesi', 'Kısa kalıplarda kafiye gerekmemesi'], 'Mesneviler binlerce beyit sürebildiği için kısa ve akıcı kalıplar anlatıyı kolaylaştırır.'),
  ('\'Mesnevi\' sözcüğünün Arapça kökündeki anlam, bu nazım şeklinin hangi özelliğine işaret eder?', 'Her beytin iki dizesinin kendi arasında kafiyelenmesine', ['Tek bir kafiyeyle bütün şiirin yazılmasına', 'Dört dizelik bentler kullanılmasına', 'Kısa ve uzun dizelerin art arda gelerek birbirini tamamlamasına'], 'Mesnevi \'ikişer ikişer\' anlamına gelir; her beyit kendi içinde kafiyelenir (aa bb cc).'),
  ('Taşlıcalı Yahya\'nın hamsesine giren mesnevilerden biri aşağıdakilerden hangisidir?', 'Gülşen-i Envar', ['Hüsn ü Aşk', 'Beng ü Bade', 'Hüsrev ü Şirin'], 'Gülşen-i Envar Yahya Bey\'in beş mesnevisinden biridir; diğer seçenekler başka şairlerin eserleridir.'),
  ('Akşemseddin\'in oğlu olan ve özellikle Yusuf u Züleyha mesnevisiyle tanınan 15. yüzyıl şairi kimdir?', 'Hamdullah Hamdi', ['Ahmed-i Dai', 'Şeyyad Hamza', 'Yazıcıoğlu Mehmed'], 'Hamdullah Hamdi, Fatih\'in hocası Akşemseddin\'in oğludur; Yusuf u Züleyha onun en tanınmış mesnevisidir.'),
  ('17. yüzyılda hamse yazan Nevizade Atai\'nin adındaki \'Nevizade\' sözcüğü neyi gösterir?', 'Şair Nev\'i\'nin oğlu olduğunu', ['Nev şehrinde doğduğunu', 'Yeni bir üslup kurduğunu', 'Nevruz bayramında doğduğu için bu adı aldığını'], '\'Zade\' oğul demektir; Atai, 16. yüzyıl şairi ve âlimi Nev\'i\'nin oğludur.'),
  ('Hüsrev ü Şirin, Leyla vü Mecnun ve Yusuf u Züleyha gibi hikâyelerin farklı şairlerce defalarca mesnevi olarak yazılması neyi gösterir?', 'Divan edebiyatında asıl ustalığın konudan çok söyleyişte aranmasını', ['Şairlerin yeni konu bulamadıkları için yazmayı bırakmalarını', 'Mesnevilerin yalnız çeviri olarak yazılmasını', 'Bu hikâyelerin tarihsel belge sayılmasını'], 'Aynı konuyu yeniden işlemek bir ustalık yarışıdır; şairler birbirinden farkı anlatımda gösterir.'),
  ('Bir mesnevinin giriş bölümleri sırayla tevhid, münacat, naat ve methiye olarak dizilmiştir. Methiye bölümünde genellikle kim övülür?', 'Eserin sunulduğu padişah ya da devlet büyüğü', ['Hikâyenin kötü kahramanı', 'Şairin kendi öğrencisi', 'Allah ve peygamberler'], 'Mesnevinin girişindeki methiye, eserin ithaf edildiği hükümdar ya da yöneticiyi över; Allah tevhidde övülür.'),
  ('Başka bir şairin gazelindeki her beytin önüne aynı ölçü ve kafiyede dört dize eklenerek altı dizelik bentler oluşturulmasına ne ad verilir?', 'Tesdis', ['Tahmis', 'Tazmin', 'Tesmin'], 'Tesdis \'altılı yapma\' anlamındadır; beyite dört dize eklenip müseddes elde edilir.'),
  ('Bir şair 5 beyitlik bir gazeli tesdis ederek müseddese dönüştürürse, eklediği dizelerin toplam sayısı kaç olur?', '20', ['10', '15', '30'], 'Her beyte 4 dize eklenir: 5 × 4 = 20 dize eklenmiş, şiir 30 dizeye ulaşmıştır.'),
  ('Her hanesi 8 beyit olan ve 6 bentten oluşan bir terkib-i bentte, vasıta beyitleri de sayılırsa toplam kaç beyit vardır?', '54', ['48', '56', '60'], 'Her bent 8 hane beyti + 1 vasıta beyti = 9 beyit; 6 × 9 = 54 beyit eder.'),
  ('Müstezatın uzun dizelerinde \'mef\'ûlü mefâîlü mefâîlü feûlün\' kalıbı kullanılırsa kısa dizelerde (ziyadelerde) genellikle hangi kalıp yer alır?', 'Mef\'ûlü feûlün', ['Fâilâtün fâilün', 'Müstef\'ilün müstef\'ilün', 'Feûlün feûlün feûlün'], 'Müstezatın ziyadesi uzun dizenin ilk ve son cüzünden oluşur: mef\'ûlü feûlün.'),
  ('Bir müstezat 6 beyitten oluşuyor ve her beyitteki iki uzun dizenin her birinin ardından bir ziyade geliyor. Uzun dizeler ve ziyadeler ayrı ayrı sayılırsa şiirde toplam kaç dize bulunur?', '24', ['12', '18', '30'], 'Her beyitte 2 uzun dize ve her birinin ardından gelen 2 ziyade vardır: 6 × 4 = 24.'),
  ('Rubai ile tuyuğu birbirinden ayırmada en güvenilir biçim ölçütü hangisidir?', 'Yazıldıkları aruz kalıpları', ['Dize sayıları', 'Bent kullanıp kullanmamaları', 'Son dizede mahlas bulunup bulunmaması'], 'İkisi de dört dizelidir ve benzer kafiyelenir; rubai ahreb-ahrem kalıplarıyla, tuyuğ fâilâtün fâilâtün fâilün kalıbıyla yazılır.'),
  ('Rubailerde dizelerin işlevine ilişkin yaygın değerlendirme hangisidir?', 'Asıl düşünce genellikle üçüncü ve dördüncü dizelerde verilir', ['İlk dize her zaman mahlası taşır', 'Dört dizenin her biri ayrı konuyu işler', 'Son dize, şiirin başındaki dizenin aynısı olarak nakarat gibi tekrarlanır'], 'Rubaide ilk iki dize konuyu hazırlar, son iki dizede düşünce çarpıcı biçimde sonuca bağlanır.'),
  ('Rubailerde \'aaxa\' düzeni yaygın olsa da bazı rubailerde dört dizenin hepsi kafiyelidir. Bu durumda rubainin kafiye düzeni nasıl gösterilir?', 'aaaa', ['abab', 'abba', 'aabb'], 'Rubailer aaxa biçiminin yanında aaaa biçiminde de kafiyelenebilir.'),
  ('Divanlarda rubailerin, gazellerden ve kasidelerden sonra genellikle hangi bölümde toplandığı görülür?', 'Divanın sonlarına doğru, ayrı bir bölümde', ['Divanın en başında, tevhidden önce', 'Her gazelin arasına dağıtılmış olarak', 'Yalnız mesnevilerin giriş bölümünde, tevhid ile naat arasında'], 'Divan tertibinde kaside ve gazellerden sonra rubai, kıta, müfred gibi küçük biçimler sona doğru yer alır.'),
  ('Tuyuğun Divan şiirine Türklerin bir katkısı sayılmasının en önemli dayanağı hangisidir?', 'Arap ve Fars edebiyatlarında bulunmayıp Türk şairlerince geliştirilmesi', ['Hece ölçüsüyle yazılması', 'Yalnız halk âşıklarınca söylenmesi', 'Bentlerden oluşması ve her bendin sonunda aynı dizenin tekrarlanması'], 'Tuyuğ Arap ve Fars şiirinde bulunmayan, Türklere özgü bir nazım şeklidir.'),
  ('Tuyuğun daha çok hangi Türk edebiyatı sahalarında yaygınlaştığı bilinir?', 'Çağatay ve Azerbaycan sahalarında', ['Yalnız İstanbul sarayında', 'Yalnız Mısır Memlük sahasında', 'Yalnız Bosna\'da'], 'Tuyuğ en çok Çağatay ve Azerbaycan sahalarında yazılmış, Anadolu\'da Kadı Burhaneddin gibi şairlerle temsil edilmiştir.'),
  ('Divan edebiyatında Hz. Muhammed\'in dış görünüşünü manzum olarak anlatan ve kendi türünün en ünlü örneği sayılan eseri 16. yüzyılın sonunda kim yazmıştır?', 'Hakani Mehmed Bey', ['Süleyman Çelebi', 'Yazıcıoğlu Mehmed', 'Erzurumlu Mustafa Darir'], 'Hakani Mehmed Bey\'in Hilye-i Hakani\'si manzum hilyelerin en tanınmışıdır.'),
  ('Hz. Muhammed\'in kırk hadisini seçip açıklayan ya da manzum olarak çeviren eserlere ne ad verilir?', 'Kırk hadis', ['Hilye', 'Siyer', 'Mevlid'], 'Kırk hadis türünde seçilen kırk hadis tercüme edilir ve açıklanır; Fuzuli\'nin de manzum bir kırk hadis çevirisi vardır.'),
  ('Fuzuli\'nin manzum kırk hadis çevirisini yaparken esas aldığı eser hangi Fars şairine aittir?', 'Molla Cami', ['Firdevsi', 'Ömer Hayyam', 'Sadi'], 'Fuzuli, Molla Cami\'nin Farsça kırk hadis manzumesini Türkçeye aktarmıştır.'),
  ('16. yüzyılda yazılmış, öğüt veren beyitleriyle tanınan ve halk arasında atasözü gibi yayılan Pendname\'nin şairi kimdir?', 'Güvahi', ['Nabi', 'Sünbülzade Vehbi', 'Taşlıcalı Yahya'], 'Güvahi\'nin Pendname\'si öğüt veren, atasözlerinden yararlanan bir mesnevidir.'),
  ('İki kavramın ya da iki varlığın kişileştirilerek birbiriyle tartıştırıldığı ve sonunda birinin üstün geldiği eserlere Divan edebiyatında ne ad verilir?', 'Münazara', ['Muamma', 'Lugaz', 'Tezkire'], 'Münazara türünde örneğin şarap ile esrar, sağlık ile hastalık gibi kavramlar tartıştırılır.'),
  ('Fuzuli\'nin Beng ü Bade\'si ile aynı türden bir eser okumak isteyen öğrenciye hangi eser önerilebilir?', 'Sıhhat ü Maraz', ['Hadikatü\'s-Süeda', 'Leyla vü Mecnun', 'Şikâyetname'], 'Sıhhat ü Maraz da Fuzuli\'nin sağlık ve hastalığı kişileştirdiği alegorik bir eserdir.'),
  ('Divan edebiyatında bir şairin müstehcen ve kaba şakalara dayanan, mizah amaçlı şiirlerine ne ad verilir?', 'Hezliyat', ['Hasbihal', 'Fahriye', 'Münacat'], 'Hezl, şaka ve latife anlamına gelir; ölçüyü aşan mizahi şiirlere hezliyat denir.'),
  ('Bir şairin divanında \'Allah\'ım, günahım çoktur ama rahmetin daha çok\' diyen bir şiir ile \'Ey Allah\'ın sevgilisi, şefaatini esirgeme\' diyen bir şiir bulunuyor. Bu şiirler sırasıyla hangi türlere örnektir?', 'Münacat ve naat', ['Tevhid ve mersiye', 'Naat ve münacat', 'Mersiye ve tevhid'], 'Allah\'a yalvarış münacat, Hz. Muhammed\'e övgü ve şefaat dileği naattır.'),
  ('Divan şiirinde iki beyitten fazla olabilen, matlaı bulunmayan ve beyitlerinin ilk dizeleri serbest olan nazım şekli kıtadır. Kıtanın daha çok hangi amaçla kullanıldığı görülür?', 'Tek bir düşünceyi, öğüdü ya da nükteyi kısa yoldan söylemek', ['Uzun aşk hikâyeleri anlatmak', 'Padişahın soy kütüğünü ayrıntılı anlatmak', 'Bestelenmek üzere dört dizelik bentlerden oluşan nakaratlı şarkılar yazmak'], 'Kıtalar kısa olduğu için genellikle bir düşünce, eleştiri ya da nükteyi işler; tarih düşürmede de sık kullanılır.'),
  ('Tarih düşürülen şiirlerde en çok hangi kısa nazım şeklinin kullanıldığı görülür?', 'Kıta', ['Mesnevi', 'Terkib-i bent', 'Müstezat'], 'Bir binanın yapımı, doğum ya da ölüm gibi olaylara düşürülen tarihler çoğu kez kıta biçiminde yazılır ve son dizede tarih verilir.'),
  ('Ebced hesabında harflerin sırası ve değerleri genellikle hangi akılda tutma sözcükleriyle ezberlenir?', 'Ebced, hevvez, huttî, kelemen, sa\'fes, karaşet, sehaz, dazıg', ['Fâilâtün, mefâîlün, müstef\'ilün, feûlün', 'Elif, be, te, se, cim, ha, hı, dal', 'Matla, makta, hüsn-i matla, beytü\'l-gazel'], 'Ebced harfleri \'ebced, hevvez, huttî...\' sözcükleriyle sıralanır; her harfe sırasına göre bir değer verilir.'),
  ('Ebced hesabında 1000 değerini taşıyan, sıralamanın son harfi hangisidir?', 'Gayın', ['Elif', 'Kaf', 'Zı'], 'Ebced sıralaması elif (1) ile başlar, gayın (1000) ile biter.'),
  ('Ebced hesabında ayın = 70, şın = 300, kaf = 100 ise ayın-şın-kaf harfleriyle yazılan \'aşk\' sözcüğünün değeri kaçtır?', '470', ['370', '400', '570'], '70 + 300 + 100 = 470 eder.'),
  ('Ebced hesabında ayın = 70, lam = 30, ye = 10 ise ayın-lam-ye harfleriyle yazılan \'Ali\' adının sayı değeri kaçtır?', '110', ['100', '120', '1100'], '70 + 30 + 10 = 110 eder.'),
  ('Ebced hesabında nun = 50, vav = 6, re = 200 değerlerine göre nun-vav-re harfleriyle yazılan \'nur\' sözcüğünün değeri kaçtır?', '256', ['206', '250', '265'], '50 + 6 + 200 = 256 eder.'),
  ('Divan şairlerinin tarih düşürürken ebced hesabıyla elde ettikleri sayı hangi takvime göre yılı verir?', 'Hicri takvim', ['Rumi takvim', 'Miladi takvim', 'Celali takvim'], 'Tarih manzumelerinde ebced toplamı hicri yılı gösterir; miladi karşılığı ayrıca hesaplanır.'),
  ('Bir şair cami yapımına tarih düşürüyor ve son dizenin bütün harflerinin ebced toplamı hicri 1026 ediyor. Bu tarih türü hangisidir?', 'Tam tarih', ['Mühmel tarih', 'Mücevher tarih', 'Ta\'miyeli tarih'], 'Dizedeki bütün harflerin değeri eksiksiz toplanınca yıl çıkıyorsa buna tam tarih denir.'),
  ('Divan şairlerinin tarih düşürme ustalığı en çok hangi tür olayları kayda geçirmekte işe yaramıştır?', 'Bina yapımı, doğum, ölüm ve tahta çıkış gibi olayların yılını', ['Yalnız şairin kendi doğum gününü', 'Yalnız savaşların kaybedildiği günleri', 'Yalnız mevsimlerin başladığı günleri ve ay tutulmalarının saatlerini kaydetmek'], 'Tarih kıtaları cami, çeşme, saray yapımı; doğum, ölüm ve cülus gibi olayların yılını korur; kitabelerde de kullanılır.'),
  ('Bir öğrenci \'Tarih düşürmede amaç yalnız yılı bildirmektir.\' diyor. Bu görüşü en iyi düzelten açıklama hangisidir?', 'Yıl, anlamlı ve sanatlı bir dize içinde gizlenerek söz ustalığı da gösterilir', ['Tarih düşürmede yıl hiçbir zaman verilmez', 'Tarih düşürme yalnız halk şiirinde görülür', 'Tarih düşürme, aruz yerine hece ölçüsüyle ve kafiyesiz dizelerle yapılmak zorundadır'], 'Tarih dizesi hem olayla ilgili anlamlı bir söz söyler hem de harf değerleriyle yılı verir; bu çifte ustalık beğenilirdi.'),
  ('Aruz ölçüsünü Arap şiiri için ilk kez kurallara bağlayan 8. yüzyıl dil bilgini kimdir?', 'Halil bin Ahmed', ['Firdevsi', 'Kâşgarlı Mahmud', 'Molla Cami'], 'Aruz, Basralı Halil bin Ahmed tarafından sistemleştirilmiş, sonra Fars ve Türk şiirine geçmiştir.'),
  ('Aruzda açık (kısa) hece nokta (.) ve kapalı (uzun) hece çizgi (-) ile gösterilirse \'fâilâtün\' tef\'ilesinin dizilişi hangisidir?', '- . - -', ['. - - -', '- - . -', '. - . -'], 'Fâ (uzun), i (kısa), lâ (uzun), tün (uzun): - . - - dizilişi elde edilir.'),
  ('\'Mef\'ûlü mefâilün feûlün\' kalıbıyla yazılmış bir dizede kaç hece bulunur?', '10', ['11', '9', '12'], 'Mef\'ûlü 3, mefâilün 4, feûlün 3 hecedir: 3 + 4 + 3 = 10.'),
  ('Aruzla yazılmış bir dizenin son hecesi açık hece olsa bile vezin bakımından nasıl değerlendirilir?', 'Uzun sayılır', ['Kısa sayılır', 'Hiç sayılmaz', 'İki hece sayılır'], 'Aruzda dize sonundaki hece, açık da olsa uzun hece kabul edilir.'),
  ('Aruzda Arapça ve Farsça sözcüklerdeki \'â, î, û\' gibi uzun ünlülerle biten açık heceler nasıl değerlendirilir?', 'Uzun hece sayılır', ['Kısa hece sayılır', 'Ölçüye katılmaz', 'Her zaman med sayılır'], 'Bu sözcüklerde ünlünün doğal uzunluğu korunur; uzun ünlülü açık hece aruzda uzundur.'),
  ('Osmanlı tarihçisi Âşıkpaşazade ile 14. yüzyıl şairi Âşık Paşa arasındaki ilişki hangisidir?', 'Âşıkpaşazade, Âşık Paşa\'nın soyundan gelir', ['İkisi aynı kişidir', 'Âşık Paşa, Âşıkpaşazade\'nin öğrencisidir', 'İkisi arasında hiçbir bağ yoktur, adların benzerliği rastlantıdır'], '\'Zade\' oğul ya da soyundan gelen demektir; tarihçi Âşıkpaşazade, Âşık Paşa\'nın torunlarındandır.'),
  ('Seyyid Nesimi, Türk edebiyatının hangi sahasının ilk büyük şairlerinden sayılır?', 'Azerbaycan sahası', ['Çağatay sahası', 'Kıpçak sahası', 'Harezm ve Altın Orda sahası'], 'Nesimi şiirlerini Azerbaycan Türkçesi özellikleri taşıyan bir dille yazmış, bu sahanın kurucu şairlerinden olmuştur.'),
  ('Erzurumlu Mustafa\'nın adına eklenen \'Darir\' lakabı onun hangi özelliğini anlatır?', 'Gözlerinin görmemesini', ['Erzurum kadısı olmasını', 'Mısır\'da doğmasını', 'Saray hocası olmasını'], 'Darir Arapçada \'âmâ, görme engelli\' demektir; şair bu lakapla anılmıştır.'),
  ('Erzurumlu Darir\'in Memlük Mısır\'ında yazdığı ve Hz. Muhammed\'in hayatını anlatan büyük eseri hangisidir?', 'Siyer-i Nebi', ['Muhammediye', 'Mevlid', 'Hilye-i Hakani'], 'Siyer-i Nebi, Darir\'in Arapçadan Türkçeye aktardığı ve genişlettiği bir siyer kitabıdır.'),
  ('Şeyhi\'nin asıl mesleği ve bu mesleğe bağlı olarak tanındığı ad hangisidir?', 'Hekimlik; Hekim Sinan', ['Kadılık; Kadı Sinan', 'Hattatlık; Hattat Yusuf', 'Askerlik; Sinan Bey'], 'Şeyhi\'nin asıl adı Sinan\'dır; hekimlikle uğraştığı için Hekim Sinan diye de anılır.'),
  ('Süleyman Çelebi Mevlid\'i yazdığı sırada hangi şehirde ve hangi görevde bulunuyordu?', 'Bursa\'da, Ulu Cami imamı olarak', ['Konya\'da, Mevlevi şeyhi olarak', 'Edirne\'de, saray şairi olarak', 'İstanbul\'da, Rumeli kazaskeri olarak'], 'Süleyman Çelebi Yıldırım Bayezid döneminde Bursa Ulu Cami\'de imamlık yapmıştır.'),
  ('Cem Sultan\'ın şiirlerinde ayrılık ve yurt özlemi temalarının yoğun olması hayatının hangi döneminden kaynaklanır?', 'Yıllarca Avrupa\'da tutsak yaşamasından', ['Kazasker olarak Anadolu\'yu dolaşmasından', 'Hac yolunda geçirdiği yıllardan', 'Mısır\'da kadılık yapmasından'], 'Taht mücadelesini kaybeden Cem, Rodos\'a ve oradan Avrupa\'ya geçmiş, ömrünün sonuna kadar orada tutsak kalmıştır.'),
  ('Ahmet Paşa\'nın, Fatih Sultan Mehmed döneminde devlet ve saray hayatında bulunduğu görevlerden biri aşağıdakilerden hangisidir?', 'Vezirlik', ['Şeyhülislamlık', 'Kaptan-ı deryalık', 'Mevlevi şeyhliği'], 'Ahmet Paşa Fatih\'in hocası ve veziri olmuş, sonra gözden düşerek Bursa\'ya gönderilmiştir.'),
  ('II. Bayezid\'in şiirlerinde kullandığı mahlas hangisidir?', 'Adli', ['Avni', 'Muhibbi', 'Bahti'], 'II. Bayezid \'Adli\' mahlasıyla şiir yazmıştır; Avni Fatih\'in, Muhibbi Kanuni\'nin, Bahti I. Ahmed\'in mahlasıdır.'),
  ('Yavuz Sultan Selim\'in divanı ile ilgili en dikkat çekici özellik hangisidir?', 'Şiirlerinin büyük bölümünü Farsça yazmış olması', ['Yalnız hece ölçüsüyle yazması', 'Divanında hiç gazel bulunmaması', 'Şiirlerini Arapça harflerle değil Latin harfleriyle yazması'], 'Yavuz Sultan Selim Selimi mahlasıyla daha çok Farsça şiirler yazmıştır.'),
  ('Hem şair hem de bestekâr olan ve şiirlerinde \'İlhami\' mahlasını kullanan Osmanlı padişahı kimdir?', 'III. Selim', ['II. Mahmud', 'III. Ahmed', 'I. Ahmed'], 'III. Selim İlhami mahlasıyla şiir yazmış, aynı zamanda Türk musikisinde önemli besteler bırakmıştır.'),
  ('Divan şiiri geleneğinde padişahların da mahlasla şiir yazmasının edebiyat hayatına başlıca etkisi ne olmuştur?', 'Şiirin saray çevresinde itibar görmesi ve şairlerin korunması', ['Aruzun bırakılıp hecenin benimsenmesi', 'Divan şiirinin halktan tamamen kopup yasaklanması', 'Nazirecilik geleneğinin sona ermesi'], 'Şiir yazan padişahlar şairleri himaye etmiş, saray şiirin önemli bir merkezi olmuştur.'),
  ('Safevi devletinin kurucusu Şah İsmail şiirlerinde hangi mahlası kullanmıştır?', 'Hatayi', ['Hüseyni', 'Fani', 'Adli'], 'Şah İsmail Türkçe şiirlerini Hatayi mahlasıyla yazmış, hem aruz hem hece kullanmıştır.'),
  ('Ali Şir Nevai\'nin Hüseyin Baykara\'nın yanındaki konumu hakkında hangisi doğrudur?', 'Hem yakın dostu hem de devlet görevlisi ve veziri olmuştur', ['Onun sarayında yalnız hattat olarak çalışmıştır', 'Ona karşı isyan edip Anadolu\'ya kaçmıştır', 'Onun torunu olarak tahta çıkmıştır'], 'Nevai, Hüseyin Baykara ile çocukluk arkadaşıdır; onun döneminde mühürdarlık ve vezirlik gibi görevlerde bulunmuştur.'),
  ('Babür Şah\'ın kendi hayatını ve Hindistan\'daki fetihlerini Çağatay Türkçesiyle anlattığı eser hangisidir?', 'Babürname', ['Mahbubü\'l-Kulub', 'Dehname', 'Muhakemetü\'l-Lugateyn'], 'Babürname, Babür\'ün anılarını içeren düzyazı bir eserdir; Babür aynı zamanda divan sahibi bir şairdir.'),
  ('Bir edebiyat tarihçisi şu bilgileri veriyor: \'Safevi hükümdarıdır, Türkçe şiirler yazmıştır, şiirleri Alevi-Bektaşi çevrelerinde de okunmuştur.\' Sözü edilen şair kimdir?', 'Hatayi', ['Nesimi', 'Fuzuli', 'Kadı Burhaneddin'], 'Şah İsmail Hatayi\'nin şiirleri tekkelerde ve Alevi-Bektaşi çevrelerinde yaygın biçimde benimsenmiştir.'),
  ('Osmanlı padişahlarının mahlaslarıyla ilgili aşağıdaki eşleştirmelerden hangisi yanlıştır?', 'III. Selim – Muhibbi', ['Fatih Sultan Mehmed – Avni', 'II. Bayezid – Adli', 'I. Ahmed – Bahti'], 'Muhibbi Kanuni Sultan Süleyman\'ın mahlasıdır; III. Selim İlhami mahlasını kullanmıştır.'),
  ('Nesimi ile Kadı Burhaneddin\'in ortak yönü olarak hangisi gösterilebilir?', 'Tuyuğ türünde başarılı örnekler vermeleri', ['İkisinin de hamse yazması', 'İkisinin de 18. yüzyılda yaşaması', 'İkisinin de Osmanlı sadrazamı olması'], '14. yüzyılın bu iki şairi tuyuğun en başarılı ilk örneklerini vermiştir.'),
  ('Fuzuli\'nin ölüm nedeni olarak kaynaklarda en çok gösterilen olay hangisidir?', 'Kerbela\'da çıkan veba salgını', ['Bağdat kuşatmasında aldığı yara', 'Padişahın emriyle idam edilmesi', 'Hac yolunda geçirdiği kaza'], 'Fuzuli 1556 yılında Kerbela\'da veba salgınında ölmüştür.'),
  ('Fuzuli\'nin \'Mende Mecnun\'dan füzun âşıklık istidadı var / Âşık-ı sadık menem Mecnun\'un ancak adı var\' beytinde şair kendini nasıl tanıtır?', 'Aşkta Mecnun\'dan bile üstün bir âşık olarak', ['Mecnun\'un öğrencisi olarak', 'Aşkı küçümseyen bir zahit olarak', 'Aşktan vazgeçmiş bir yaşlı olarak'], 'Şair, Mecnun\'un yalnız adının kaldığını, gerçek âşığın kendisi olduğunu söyleyerek aşktaki üstünlüğünü dile getirir.'),
  ('Fuzuli\'nin \'Ya Rab bela-yı aşk ile kıl aşina beni / Bir dem bela-yı aşktan kılma cüda beni\' beytinde dikkat çeken tutum hangisidir?', 'Aşkın acısını bir lütuf gibi Allah\'tan istemesi', ['Aşkın acısından kurtulmak için dua etmesi', 'Sevgiliyi yererek ondan ayrılması', 'Dünya zevklerini övüp aşkı küçümsemesi'], 'Şair aşk belasından kurtulmayı değil, ondan hiç ayrılmamayı diler; bu, Fuzuli\'deki ıstırabı sevme tavrının bir örneğidir.'),
  ('Fuzuli\'nin, Kanuni Sultan Süleyman\'ın 1534\'te Bağdat\'ı almasının ardından yaptığı edebî girişim hangisidir?', 'Padişaha ve devlet adamlarına kasideler sunması', ['Bağdat\'tan kaçarak İran\'a yerleşmesi', 'Şiiri bırakıp kadılık yapması', 'Osmanlılara karşı hicivler yazması'], 'Bağdat\'ın Osmanlılarca alınmasından sonra Fuzuli Kanuni\'ye ve devlet adamlarına kasideler sunmuştur.'),
  ('Fuzuli\'nin Leyla vü Mecnun\'u ile Hadikatü\'s-Süeda\'sını karşılaştıran bir öğrenci hangi ortak yönü doğru olarak saptar?', 'İkisinde de acı ve ıstırabın merkezde olması', ['İkisinin de Farsça yazılması', 'İkisinin de mizahi olması', 'İkisinin de tezkire olması'], 'Biri aşk acısını, öteki Kerbela faciasını anlatır; Fuzuli\'nin ıstırap temasına bağlılığı her iki eserde de görülür.'),
  ('Baki\'nin \'Kadrini seng-i musallada bilip ey Baki / Durup el bağlayalar karşına yaran saf saf\' beytinde anlatılan düşünce hangisidir?', 'İnsanın değerinin ancak öldükten sonra anlaşılacağı', ['Dostların her zaman vefalı olduğu', 'Namaz kılmanın önemi', 'Sevgilinin acımasızlığının âşığı ölüme sürüklediği'], 'Musalla taşı cenaze namazının kılındığı taştır; şair, dostlarının onun değerini ancak cenazesinde saf saf durunca anlayacağını söyler.'),
  ('Gençliğinde kalenderi dervişlerle dolaşan, sonra İbrahim Paşa\'nın himayesiyle saraya giren 16. yüzyıl şairi kimdir?', 'Hayali', ['Necati', 'Lamii', 'Bağdatlı Ruhi'], 'Hayali Bey, kalenderilerle dolaştıktan sonra İbrahim Paşa ve Kanuni\'nin himayesine girmiştir.'),
  ('Çizmecilikle geçimini sağladığı bilinen şair Zati\'nin doğduğu şehir hangisidir?', 'Balıkesir', ['Kastamonu', 'Amasya', 'Kahramanmaraş'], 'Zati Balıkesirli\'dir; sonradan İstanbul\'a gelip şiir çevrelerinde tanınmıştır.'),
  ('Taşlıcalı Yahya\'nın hayatı ile ilgili hangisi doğrudur?', 'Asker olarak seferlere katılmış bir şairdir', ['Hayatını Bağdat\'ta medrese hocası olarak geçirmiştir', 'Osmanlı\'da şeyhülislamlık yapmıştır', 'Lale Devri\'nde yaşamıştır'], 'Dukakinoğulları\'ndan olan Yahya Bey devşirme olarak alınmış, sipahi olarak birçok sefere katılmıştır.'),
  ('16. yüzyılda bazı şairlerin aruzla yazdıkları şiirlerde Arapça ve Farsça sözcükleri kullanmamaya çalıştıkları akımın adı nedir?', 'Türki-i basit', ['Sebk-i Hindi', 'Mahallileşme', 'Hikemi tarz'], 'Türki-i basit \'yalın Türkçe\' anlamına gelir; şairler aruzu koruyup yabancı sözcükleri dışlamaya çalışmıştır.'),
  ('Türki-i basit akımının geniş bir etki yaratamamasının en önemli nedeni olarak hangisi gösterilir?', 'Aruzun Türkçe sözcüklerle uyumunun güç olması', ['Padişahın bu şiirleri yasaklaması', 'Şairlerin hece ölçüsünü kullanması', 'Akımın şiirde değil yalnız nesir alanında, münşeatta kalması'], 'Uzun ünlü bulunmayan Türkçe sözcüklerle aruz kalıplarını doldurmak zordu; bu yüzden akım sınırlı kaldı.'),
  ('Nazire mecmualarının edebiyat tarihi açısından değeri en çok hangi noktadadır?', 'Divanı bugüne ulaşmamış şairlerin şiirlerini de korumaları', ['Yalnız tek bir şairin şiirlerini içermeleri', 'Şairlerin hayatlarını ayrıntılı anlatmaları', 'Aruz kurallarını örnek beyitlerle ayrıntılı biçimde öğretmeleri'], 'Nazire mecmuaları birçok şairin şiirlerini bir arada sunduğundan kaybolmuş divanlardan parçaları da günümüze taşır.'),
  ('17. yüzyılda yazılan ve Riyazü\'ş-Şuara adını taşıyan şuara tezkiresinin yazarı kimdir?', 'Riyazi', ['Kafzade Faizi', 'Güfti', 'Ahdi'], 'Riyazi, adını kendi mahlasından alan Riyazü\'ş-Şuara tezkiresinin yazarıdır; ayrıca bir sakinamesi vardır.'),
  ('Bir öğrenci, 16. yüzyıl şairleri hakkında çağdaş tanıklıklara ulaşmak istiyor. Aşağıdaki eserlerden hangisi bu amaca en uygundur?', 'Meşairü\'ş-Şuara', ['Hatimetü\'l-Eş\'ar', 'Hüsn ü Aşk', 'Hayriyye'], 'Aşık Çelebi\'nin Meşairü\'ş-Şuara\'sı 16. yüzyılda yazıldığı için o dönemin şairleri hakkında ilk elden bilgi verir; Hatimetü\'l-Eş\'ar 19. yüzyıla aittir.'),
  ('Nefi\'nin doğduğu yer olarak kaynaklarda gösterilen kasaba hangi ilin sınırları içindedir?', 'Erzurum', ['Diyarbakır', 'Kastamonu', 'Edirne'], 'Nefi Erzurum\'un Hasankale kasabasında doğmuştur.'),
  ('Rivayete göre IV. Murad Siham-ı Kaza\'yı okurken yakınına yıldırım düşmüş ve padişah kitabı parçalamıştır. Bu anlatı Nefi hakkında hangi düşünceyi pekiştirir?', 'Hicivlerinin tehlikeli ve uğursuz sayıldığını', ['Kasidelerinin padişahı sevindirdiğini', 'Nefi\'nin tasavvufa yöneldiğini', 'Siham-ı Kaza\'nın bir mesnevi olduğunu'], 'Anlatı, Nefi\'nin sert hicivlerinin çevresinde korku ve tedirginlik yarattığını gösterir; sonunda şair bu hicivler yüzünden öldürülmüştür.'),
  ('Şeyhülislam Yahya\'nın babası da şeyhülislamdır. Bu durum Şeyhülislam Yahya\'nın yetiştiği çevre hakkında neyi gösterir?', 'Köklü bir ilmiye ailesinden geldiğini', ['Sarayda hattat olarak yetiştiğini', 'Asker bir aileden geldiğini', 'Tekkede dervişlerle büyüdüğünü'], 'Şeyhülislam Yahya, Şeyhülislam Zekeriyya Efendi\'nin oğludur; ilmiye sınıfına mensup bir aileden gelir.'),
  ('Bosnalı Alaeddin Sabit\'in şiirinin en belirgin özelliği hangisidir?', 'Atasözü ve deyimleri bolca kullanması', ['Yalnız Farsça yazması', 'Bütün şiirlerini hece ölçüsüyle yazması', 'Şiirlerinde hiç mazmun bulunmaması'], 'Sabit, halk söyleyişlerini, atasözü ve deyimleri şiirine bolca taşıyarak mahallileşmenin habercilerinden olmuştur.'),
  ('Nefi\'nin kasideleri ile Nabi\'nin şiirleri karşılaştırıldığında aradaki temel fark hangisidir?', 'Nefi\'de coşkulu övgü, Nabi\'de öğüt öne çıkar', ['Nefi hece, Nabi aruz kullanır', 'Nefi yalnız Farsça, Nabi yalnız Arapça yazar', 'Nefi mesnevi, Nabi tuyuğ ustasıdır'], 'Nefi kaside ve hicivde abartılı bir coşku taşırken Nabi hikemi şiirle öğüt ve düşünce ağırlıklı bir yol izlemiştir.'),
  ('17. yüzyılda Divan şiirinde aynı dönemde birbirinden farklı üslupların bir arada bulunması neyi gösterir?', 'Kaside, hikemi tarz ve Sebk-i Hindi gibi farklı yönelimlerin geliştiğini', ['Şiirin yalnız tek bir tarza indirgendiğini', 'Divan şiirinin bu yüzyılda sona erdiğini', 'Bütün şairlerin hece ölçüsüne geçtiğini'], 'Nefi kasidede, Nabi hikemi şiirde, Naili ve Neşati Sebk-i Hindi\'de öne çıkar; bu, yüzyılın çeşitliliğini gösterir.'),
  ('Naili, Neşati ve Fehim-i Kadim adlarını bir araya getiren ortak özellik aşağıdakilerden hangisidir?', 'Sebk-i Hindi üslubunu benimsemeleri', ['Türki-i basit akımına katılmaları', 'Hamse sahibi olmaları', 'Şuara tezkiresi yazmaları'], 'Bu üç şair de 17. yüzyılda kapalı anlam ve ince hayallere dayanan Sebk-i Hindi üslubunun temsilcileridir.'),
  ('Nedim\'in ölümü hangi tarihî olay sırasında gerçekleşmiştir?', 'Patrona Halil İsyanı', ['Kabakçı Mustafa İsyanı', 'Vaka-i Hayriye', 'Edirne Vakası'], 'Nedim 1730\'da Lale Devri\'ni sona erdiren Patrona Halil İsyanı sırasında ölmüştür.'),
  ('Koca Ragıp Paşa\'nın şair kimliğinin yanında devlet hayatındaki en yüksek görevi hangisidir?', 'Sadrazamlık', ['Şeyhülislamlık', 'Kaptan-ı deryalık', 'Kazaskerlik'], 'Ragıp Paşa III. Mustafa döneminde sadrazamlık yapmış, İstanbul\'da bir kütüphane de kurdurmuştur.'),
  ('18. yüzyılda yaşamış Fıtnat Hanım ile ilgili hangisi doğrudur?', 'Şeyhülislam kızı olan, nükteli şiirleriyle tanınan bir kadın şairdir', ['Lale Devri\'nin sadrazamıdır', 'İlk Türk romanını yazmıştır', 'Mevlevihanede şeyhlik yapmıştır'], 'Fıtnat Hanım, Şeyhülislam Esad Efendi\'nin kızıdır; Koca Ragıp Paşa ile nükteli atışmalarıyla bilinir.'),
  ('Yenişehirli Avni için edebiyat tarihlerinde en sık yapılan değerlendirme hangisidir?', 'Divan şiirinin son güçlü temsilcilerinden biridir', ['Hece ölçüsüyle yazan ilk şairdir', 'Lale Devri\'nin şarkı ustasıdır', 'Türki-i basit akımının kurucusudur'], 'Yenişehirli Avni 19. yüzyılda klasik şiiri başarıyla sürdüren son büyük Divan şairleri arasında sayılır.'),
  ('Bir öğrenci Seyyid Vehbi ile Sünbülzade Vehbi\'yi karıştırıyor. Onu doğru yönlendirecek bilgi hangisidir?', 'Surname Seyyid Vehbi\'nin, Lutfiyye Sünbülzade Vehbi\'nindir', ['İkisi aynı kişinin iki mahlasıdır', 'Sünbülzade Vehbi 16. yüzyılda yaşamıştır', 'Seyyid Vehbi Tuhfe sözlüğünü yazmıştır'], 'İki şair aynı mahlası kullansa da Seyyid Vehbi Lale Devri\'nde Surname\'yi, Sünbülzade Vehbi yüzyılın sonunda Lutfiyye ve Tuhfe\'yi yazmıştır.'),
  ('Hüsn ü Aşk\'ta Hüsn ile Aşk\'ın aynı gece doğduğu kabilenin adı nedir?', 'Beni Mahabbet', ['Beni Amir', 'Beni Ümeyye', 'Beni Hilal-i Arab'], 'Hüsn ve Aşk, \'sevgi oğulları\' anlamındaki Beni Mahabbet kabilesinde aynı gece doğar.'),
  ('Hüsn ü Aşk\'ta Hüsn ile Aşk\'ın birlikte okudukları okulun hocası kimdir?', 'Molla-yı Cünun', ['Sühan', 'Gayret', 'Molla-yı Akl-ı Kül'], 'İkisi Mekteb-i Edeb\'de Molla-yı Cünun\'dan ders alır; \'cünun\' delilik anlamına gelir ve aşkın aklı aşan yönünü simgeler.'),
  ('Hüsn ü Aşk\'ta Aşk\'ın, Hüsn ile evlenebilmesi için gitmesi istenen ülke hangisidir?', 'Kalp ülkesi', ['Çin ülkesi', 'Mısır ülkesi', 'Hindistan ve Habeş ülkeleri'], 'Kabile büyükleri Aşk\'tan Kalp ülkesine gidip kimya getirmesini ister; yolculuk insanın kendi gönlüne dönüşünü simgeler.'),
  ('Hüsn ü Aşk\'ta Aşk\'ın yolculuğu boyunca yanında bulunan ve ona yardım eden yol arkadaşı kimdir?', 'Gayret', ['Sühan', 'Hüsn', 'Molla-yı Cünun'], 'Gayret, Aşk\'a yolculuğunda eşlik eder ve tehlikelerden kurtulmasına yardım eder.'),
  ('Şeyh Galip Hüsn ü Aşk\'ı hayatının hangi döneminde yazmıştır?', 'Yirmili yaşlarında, kısa bir sürede', ['Yetmiş yaşını geçtikten sonra', 'Çocukluğunda, on yaşındayken', 'Ölümünden sonra öğrencileri tamamlamıştır'], 'Şeyh Galip Hüsn ü Aşk\'ı 26 yaşında, birkaç ay içinde tamamlamıştır.'),
  ('Şeyh Galip\'in asıl adı hangisidir?', 'Mehmed Esad', ['Ahmed Nedim', 'Yusuf Nabi', 'Mehmed Ragıp Efendi'], 'Şeyh Galip\'in asıl adı Mehmed Esad\'dır; Galip mahlasıdır.'),
  ('Şeyh Galip\'i himaye eden ve onunla yakın dostluk kuran padişah kimdir?', 'III. Selim', ['III. Ahmed', 'IV. Murad', 'II. Mahmud'], 'III. Selim Mevleviliğe yakınlığı ve şiir sevgisiyle Şeyh Galip\'i korumuş, ona Galata Mevlevihanesi\'ni onarttırmıştır.'),
  ('\'Sakın terk-i edebden kûy-i Mahbub-ı Hüda\'dır bu / Nazargâh-ı ilahidir makam-ı Mustafa\'dır bu\' beytiyle başlayan ünlü naatın şairi kimdir?', 'Nabi', ['Fuzuli', 'Nedim', 'Şeyh Galip'], 'Bu naat Nabi\'nin en tanınmış şiirlerindendir ve Hz. Muhammed\'in kabrinin bulunduğu yerde edebe uyulmasını öğütler.'),
  ('\'Sakın terk-i edebden kûy-i Mahbub-ı Hüda\'dır bu\' dizesinde şair okuyucudan ne istemektedir?', 'Kutsal bir mekânda saygıyı elden bırakmamasını', ['Dünya zevklerine dalmasını', 'Sevgiliyi terk etmesini', 'Hacca gitmekten vazgeçmesini'], '\'Terk-i edeb\' edebi bırakmak demektir; şair, Allah\'ın sevgilisinin semtinde edebe aykırı davranılmamasını öğütler.'),
  ('Hüsn ü Aşk\'ın mesnevi olmasına karşın aralarına gazel ve başka biçimde şiirler de yerleştirilmesi neyi gösterir?', 'Şairin farklı nazım biçimlerini bir arada kullanma ustalığını', ['Eserin yarım kaldığını', 'Eserin birden çok şair tarafından yazıldığını', 'Eserin hece ölçüsüyle yazıldığını'], 'Şeyh Galip mesnevinin anlatısı içine gazeller ve bentli şiirler koyarak eseri zenginleştirmiştir.'),
  ('Hüsn ü Aşk\'ın sonunda Aşk\'ın aradığı sevgilinin aslında kendi içinde olduğunu anlaması, tasavvufun hangi düşüncesine dayanır?', 'Varlığın birliği (vahdet-i vücud) düşüncesine', ['Dünyanın sonsuzluğu düşüncesine', 'Aklın aşka üstünlüğü düşüncesine', 'Kaderin reddi düşüncesine'], 'Seven ile sevilenin özde bir olduğu fikri vahdet-i vücud anlayışının şiire yansımasıdır.'),
  ('Şeyh Galip\'in Fuzuli, Nedim ve Nefi\'den hangi yönüyle ayrıldığı söylenebilir?', 'Divan şiirinin 18. yüzyıl sonunda yetişmiş Mevlevi şeyhi olması', ['Hiç gazel yazmamış olması', 'Yalnız Farsça yazmış olması', 'Lale Devri\'nin şairi olması'], 'Fuzuli 16., Nefi 17., Nedim 18. yüzyılın başında yaşamıştır; Şeyh Galip ise yüzyılın sonunda yaşamış bir Mevlevi şeyhidir.'),
  ('Hüsn ü Aşk\'ı okuyan bir öğrenci, Aşk\'ın yolculuğunda karşılaştığı kuyu ve cadı gibi engellerin neyi simgelediğini soruyor. En uygun yanıt hangisidir?', 'Manevi yolculukta insanın aşması gereken nefsani engelleri', ['Osmanlı\'nın yaptığı savaşları', 'Şairin gerçek seyahatlerini', 'Yalnız masal süsünü'], 'Alegorik anlatıda engeller, insanın olgunlaşma yolunda aşması gereken dünya bağlarını ve nefsin tuzaklarını temsil eder.'),
  ('Divan şiirinde konu bakımından sınırlandırılmış, yani yalnız belli bir konuda yazılabilen nazım şekli hangisi değildir?', 'Mesnevi', ['Mersiye', 'Naat', 'Münacat'], 'Mersiye, naat ve münacat aslında konu türleridir; mesnevi ise her konuda kullanılabilen bir nazım şeklidir.'),
  ('Aşağıdaki eşleştirmelerden hangisi yüzyıl ile o yüzyılın öne çıkan üslubu bakımından yanlıştır?', '16. yüzyıl – Türki-i basit akımının bütün şiire egemen olması', ['17. yüzyıl – Sebk-i Hindi', '18. yüzyıl – Mahallileşme', '17. yüzyıl – Hikemi şiir'], 'Türki-i basit 16. yüzyılda ortaya çıkmış küçük bir akımdır; şiire egemen olmamıştır.'),
  ('Divan şiirinde mahallileşme ile Türki-i basit akımı arasındaki temel fark hangisidir?', 'Mahallileşme yerli hayatı şiire taşır, Türki-i basit dil sadeliğini hedefler', ['İkisi de hece ölçüsünü benimser', 'İkisi de 13. yüzyılda ortaya çıkmıştır', 'Mahallileşme Farsçayı, Türki-i basit Arapçayı yasaklar'], 'Mahallileşme konu ve söyleyişte yerliliği, Türki-i basit ise yabancı sözcüklerden arınmış bir dili amaçlar.'),
  ('Sebk-i Hindi üslubunun Osmanlı şiirine yayılmasında hangi kaynak doğrudan etkili olmuştur?', 'Hindistan\'da yaşamış İranlı şairlerin şiirleri', ['Çin şiir antolojileri', 'Yunan tragedyaları', 'Türk halk koşmaları ve âşıkların atışmaları'], 'Babürlü sarayında yaşayan Örfi ve Saib gibi İranlı şairlerin üslubu Hint üslubu adıyla Osmanlı şiirini etkilemiştir.'),
  ('18. yüzyıl sonunda Şeyh Galip\'in Sebk-i Hindi\'yi yeniden canlandırması ile aynı yüzyılın başında Nedim\'in mahallileşmesi karşılaştırıldığında ne söylenebilir?', 'Aynı yüzyılda biri kapalı, öteki açık iki ayrı yönelim gelişmiştir', ['İkisi de Türki-i basit akımına bağlıdır', 'İkisi de hece ölçüsünü kullanmıştır', 'İki şair de Tanzimat\'ın öncüsü olup Batı şiirini örnek almıştır'], 'Nedim yerli ve açık bir söyleyiş, Şeyh Galip ise girift hayallere dayanan kapalı bir üslup benimsemiştir.'),
  ('Divan şiirinde sevgilinin yüzündeki siyah ben, rengi nedeniyle çoğu zaman kime benzetilir?', 'Hinduya', ['Araba', 'Rumluya', 'Frenk elçisine'], 'Siyah ben, esmer tenli olduğu düşünülen Hindulara benzetilir; \'Hindu ben\' mazmunu bu yüzden yaygındır.'),
  ('Divan şiirinde aşk acısıyla iki büklüm olmuş âşığın boyu genellikle hangi harfe benzetilir?', 'Dal', ['Elif', 'Lam', 'Ye'], 'Dal harfi kıvrık bir biçime sahiptir; bükülmüş âşık bedeni bu harfle anlatılır.'),
  ('Divan şiirinde lalenin ortasındaki siyah leke, âşıkla ilgili hangi durumu simgeler?', 'Aşk ateşiyle yanmış bağrı', ['Sevgiliye kavuşmanın sevincini', 'Âşığın zenginliğini', 'Baharın sona ermesini'], 'Lalenin bağrındaki siyahlık, aşk ateşiyle kararmış yürek olarak yorumlanır.'),
  ('Divan şiirinde boynunu büken çiçek olarak anılan ve bu yüzden mahzun âşığa benzetilen çiçek hangisidir?', 'Menekşe', ['Lale', 'Gül', 'Nergis'], 'Menekşenin eğik duruşu boynu bükük, mahzun âşığı anlatmak için kullanılır.'),
  ('Divan şiirinde sevgilinin yanağındaki ince tüyler (hat) genellikle neye benzetilir?', 'Yazıya ve yeşeren çimene', ['Kara bulutlara', 'Deniz dalgalarına', 'Dağ sırtlarındaki kayalara ve uçurumlara'], 'Hat, gül yüzün üzerinde yazılmış bir yazıya ya da gül bahçesinde yeşeren çimene benzetilir.'),
  ('Divan şiirinde sevgilinin bulunduğu semte, yani sokağına verilen ad hangisidir?', 'Kûy', ['Bezm', 'Harabat', 'Gülşen'], 'Kûy sevgilinin mahallesi ya da sokağıdır; âşık onun çevresinde dolaşmayı arzular.'),
  ('Divan şiirinde sevgilinin dudağı için hem \'can bağışlayan\' hem de \'şarap gibi sarhoş eden\' denmesi, bu mazmunun hangi özelliğini gösterir?', 'Bir unsurun birden çok anlam katmanıyla işlenmesini', ['Mazmunların hiç değişmemesini', 'Dudak mazmununun yalnız bir anlam taşımasını', 'Şairlerin benzetme kullanmamasını'], 'Divan şiirinde aynı güzellik unsuru farklı ilişkilerle zenginleştirilir; dudak hem Mesih nefesi gibi diriltir hem şarap gibi sarhoş eder.'),
  ('Divan şiirinde \'Cam-ı Cem\' (Cem\'in kadehi) neden önemli bir mazmundur?', 'İçinde bütün dünyanın görüldüğüne inanılan bir kadeh olduğu için', ['Hiç boşalmayan bir su kabı olduğu için', 'Altından yapılmış bir taç olduğu için', 'Ölüleri dirilten bir şerbet içerdiği için'], 'Efsanevi İran hükümdarı Cemşid\'in kadehinde dünyanın bütün olayları görülürdü; şairler gönlü ya da şarap kadehini buna benzetir.'),
  ('Divan şiirinde oğlunun ayrılığıyla ağlamaktan gözleri kör olan ve \'hüzün evi\'nde (beytü\'l-hazen) yaşayan peygamber kimdir?', 'Hz. Yakup', ['Hz. Yusuf', 'Hz. Eyüp', 'Hz. Nuh Nebi'], 'Hz. Yakup oğlu Yusuf\'un ayrılığında ağlamaktan gözlerini yitirmiştir; ayrılık acısı çeken âşık ona benzetilir.'),
  ('Divan şiirinde ateşte yaşadığına inanılan ve bu yüzden aşk ateşinde yanmaktan korkmayan âşığa benzetilen yaratık hangisidir?', 'Semender', ['Hüma', 'Anka', 'Hüdhüd'], 'Semender ateşte yaşayan efsanevi bir yaratıktır; aşk ateşine alışmış âşık onunla anılır.'),
  ('Divan şiirinde felsefe ve hikmetin simgesi olarak anılan, şiirlerde bir küpün içinde yaşadığı söylenen filozof kimdir?', 'Eflatun', ['Lokman', 'Aristo', 'Bokrat'], 'Divan şiirinde Eflatun hikmetin simgesidir ve küp içinde yaşadığı söylenir; bu inanç Diyojen\'e ait bir anlatının ona aktarılmasından doğmuştur.'),
  ('Divan şiirinde Ferhat\'ın elindeki aletle anılan \'külünk\' ne işe yarar?', 'Dağ delmeye yarayan kazmaya', ['Su içmeye yarayan kaba', 'Şiir yazmaya yarayan kaleme', 'Ok atmaya yarayan, geyikten yapılmış yaya'], 'Külünk bir tür kazmadır; Ferhat Şirin için dağı bu aletle deler.'),
  ('Bir şair, \'Gönlümün aynasında bütün âlemi görürüm\' diyerek gönlünü hangi efsanevi nesneye benzetmiş olabilir?', 'Cem\'in kadehine', ['Süleyman\'ın mührüne', 'Musa\'nın asasına', 'Ferhat\'ın külüngüne'], 'Cam-ı Cem\'de dünyanın bütün olayları görülür; gönlü âlemi gösteren bir aynaya ya da kadehe benzetmek bu mazmuna dayanır.'),
  ('Divan şiirinde sık geçen \'bezm\' ve \'rezm\' sözcükleri sırasıyla neyi anlatır?', 'Eğlence meclisini ve savaşı', ['Savaşı ve barışı', 'Sabahı ve akşamı', 'Baharın gelişini ve kışın sona erişini'], 'Bezm içki ve sohbet meclisi, rezm ise savaş demektir; övülen padişahın hem mecliste hem savaşta üstünlüğü bu ikiliyle anlatılır.'),
  ('Divan şiirinde \'bezm-i elest\' ifadesi hangi inanışa dayanır?', 'Ruhların yaratılışta Allah\'ın \'Ben sizin Rabbiniz değil miyim?\' sorusuna \'Evet\' dediği meclise', ['Padişahın bayram sabahı verdiği ziyafete', 'Şairlerin her yıl yaptığı şiir yarışmasına', 'Peygamberin hicret gecesine'], 'Elest bezmi, ruhların ezelde Allah\'la söz verdiği andır; âşıklar aşkın o gün başladığını söyler.'),
  ('Halkın kınamasına aldırmadan, iyiliklerini gizleyip kendini kusurlu gösteren tasavvufi anlayışa ne ad verilir?', 'Melamet', ['Riya', 'Zühd', 'Kesret-i vücud'], 'Melamet, gösterişten kaçıp kınanmayı göze almaktır; Divan şairleri âşığın \'kınanmaktan korkmaması\'nı bu anlayışla işler.'),
  ('Divan şairlerinin mahlaslarının seçilmesi ile ilgili yaygın uygulama hangisidir?', 'Çoğu zaman hocalarının ya da usta bir şairin mahlas vermesi', ['Padişahın bütün şairlere aynı mahlası vermesi', 'Mahlasın kura ile belirlenmesi', 'Mahlasın yalnız doğum yerinden alınması'], 'Genç şairler çoğu zaman bir ustanın yanında yetişir ve mahlaslarını ondan alırdı; bazıları kendisi de seçerdi.'),
  ('Divan şiirinde \'aşk-ı mecazi\' kavramı tasavvufi bakışla nasıl değerlendirilir?', 'Gerçek aşka, yani ilahi aşka ulaştıran bir köprü olarak', ['Tamamen yasak bir duygu olarak', 'Yalnız masallarda görülen bir aşk olarak', 'Âşığı Allah\'tan uzaklaştıran bir engel olarak'], '\'El-mecazü kantaratü\'l-hakika\' sözüyle insana duyulan aşk, ilahi aşka giden bir köprü sayılır.'),
  ('Divanların başında, şairin eserini neden ve nasıl düzenlediğini anlattığı düzyazı önsöze ne ad verilir?', 'Dibace', ['Hatime', 'Zeyl', 'Sebeb-i telif'], 'Dibace, divanın ya da bir eserin başındaki önsözdür; Fuzuli\'nin divan önsözleri bunun ünlü örneklerindendir.'),
  ('Divanın kasideler bölümü genellikle hangi tür kasidelerle açılır?', 'Tevhid, münacat ve naatlarla', ['Hicviyelerle', 'Mersiyelerle', 'Fahriye ve girizgâh bölümleriyle'], 'Divanlar dinî kasidelerle başlar; ardından padişah ve devlet büyüklerine yazılan methiyeler gelir.'),
  ('Bir şairin divanı, mesnevileri ve düzyazı eserleri gibi bütün eserlerinin bir arada toplandığı cilde ne ad verilir?', 'Külliyat', ['Divançe', 'Dibace', 'Şuara tezkiresi'], 'Külliyat bir yazarın tüm eserlerinin toplamıdır; divan ise yalnız şiirlerini içerir.'),
  ('Farklı şairlerin beğenilen şiirlerinin bir kişi tarafından deftere toplanmasıyla oluşan yazma derlemelere ne ad verilir?', 'Mecmua', ['Divan', 'Külliyat', 'Dibace'], 'Şiir mecmuaları farklı şairlerden seçilmiş şiirleri içerir; birçok şiirin bugüne ulaşmasını sağlamıştır.'),
  ('Ahmet Paşa\'nın son yıllarını geçirdiği ve öldüğü şehir hangisidir?', 'Bursa', ['Edirne', 'Konya', 'Kastamonu'], 'Fatih\'in gözünden düşen Ahmet Paşa Bursa\'ya gönderilmiş, II. Bayezid döneminde orada ölmüştür.'),
  ('Divanlarda kaside bölümünün \'kasaid\', gazel bölümünün \'gazeliyyat\' diye adlandırılması aşağıdakilerden hangisini gösterir?', 'Şiirlerin nazım şekillerine göre gruplandığını', ['Şiirlerin yazıldığı yıla göre dizildiğini', 'Şiirlerin uzunluğuna göre sıralandığını', 'Şiirlerin sunulduğu kişilere göre ayrıldığını'], 'Divan tertibinde şiirler önce nazım şekline göre bölümlere ayrılır; gazeller de kendi içinde redif harfine göre dizilir.'),
  ('Leyla ile Mecnun hikâyesinde Leyla\'nın ailesinin zorlamasıyla evlendiği kişi kimdir?', 'İbn Selam', ['Nevfel', 'Şapur', 'Leyla\'nın amcasının oğlu'], 'Leyla, İbn Selam ile evlendirilir ama ona gönlünü vermez; bu evlilik hikâyenin trajik yönünü güçlendirir.'),
  ('Leyla ile Mecnun hikâyesinde Mecnun\'a acıyıp onun için Leyla\'nın kabilesiyle savaşan Arap beyi kimdir?', 'Nevfel', ['İbn Selam', 'Hüsrev', 'Şapur'], 'Nevfel, Mecnun\'a yardım için Leyla\'nın kabilesine savaş açar, ama Mecnun savaşta sevgilisinin kabilesini tutar.'),
  ('Hüsrev ü Şirin hikâyesinde Hüsrev\'in resmini Şirin\'e göstererek onu Hüsrev\'e âşık eden ressam kimdir?', 'Şapur', ['Ferhat', 'Nevfel', 'Şiruye'], 'Hüsrev\'in dostu nakkaş Şapur, resmi yoluyla Şirin\'in gönlünde Hüsrev sevgisini uyandırır.'),
  ('Hüsrev ü Şirin hikâyesinde Hüsrev\'in kimin tarafından öldürüldüğü anlatılır?', 'Oğlu Şiruye', ['Ferhat', 'Şapur', 'Mehin Banu\'nun askerleri'], 'Hüsrev, oğlu Şiruye tarafından öldürülür; Şirin de onun mezarı başında canına kıyar.'),
  ('Yusuf u Züleyha mesnevilerinde Züleyha\'nın hikâyenin sonundaki durumu genellikle nasıl anlatılır?', 'Gençliğine kavuşup Yusuf ile evlenir', ['Mısır\'dan kaçıp çölde ölür', 'Yusuf\'u zindanda bırakıp unutur', 'Kardeşleriyle birlikte Kenan\'a döner'], 'Mesnevi geleneğinde yaşlanıp gözlerini yitiren Züleyha, Yusuf\'un duasıyla gençleşir ve onunla evlenir.'),
  ('Aşağıdaki şairler yaşadıkları döneme göre eskiden yeniye doğru sıralanırsa hangisi en sonda yer alır?', 'Yenişehirli Avni', ['Şeyh Galip', 'Nabi', 'Necati Bey'], 'Necati 15., Nabi 17., Şeyh Galip 18. yüzyıl sonunda, Yenişehirli Avni ise 19. yüzyılda yaşamıştır.'),
  ('Aşağıdaki eserlerden hangisi 16. yüzyılda yazılmıştır?', 'Leyla vü Mecnun (Fuzuli)', ['Hüsn ü Aşk', 'Hayriyye', 'Harname (Şeyhi)'], 'Fuzuli\'nin Leyla vü Mecnun\'u 16. yüzyıla, Harname 15., Hayriyye 17., Hüsn ü Aşk 18. yüzyıla aittir.'),
  ('Aşağıdaki eser-şair eşleştirmelerinden hangisi yanlıştır?', 'Gencine-i Raz – Nabi', ['Rind ü Zahid – Fuzuli', 'Defter-i Aşk – Enderunlu Fazıl', 'Tervihü\'l-Ervah – Ahmedi'], 'Gencine-i Raz Taşlıcalı Yahya\'nın hamsesine aittir; diğer eşleştirmeler doğrudur.'),
  ('Erken dönem ve klasik dönem mesnevilerinden söz eden bir öğretmen, tahtaya dört eser ile yazar adı yazıyor. Hangisini doğru yazmıştır?', 'Çengname – Ahmed-i Dai', ['Surname-i Vehbi – Sünbülzade Vehbi', 'Felekname – Şeyhi', 'Lisanü\'t-Tayr – Gülşehri'], 'Çengname Ahmed-i Dai\'nindir; Surname-i Vehbi Seyyid Vehbi\'nin, Felekname Gülşehri\'nin, Lisanü\'t-Tayr Nevai\'nindir.'),
  ('Bir şairin özellikleri şunlardır: \'Germiyan çevresinde yetişti, hekimdi, Nizami\'den bir aşk mesnevisi aktardı, bir hiciv mesnevisi yazdı.\' Bu şair kimdir?', 'Şeyhi', ['Ahmedi', 'Ahmed-i Dai', 'Ahmet Paşa'], 'Hekimlik, Hüsrev ü Şirin ve Harname birlikte Şeyhi\'yi gösterir.'),
  ('Bir şairin özellikleri şunlardır: \'18. yüzyılda yaşadı, Maraşlıdır, çocuklar için manzum sözlükler yazdı, oğluna öğüt veren bir mesnevi kaleme aldı.\' Bu şair kimdir?', 'Sünbülzade Vehbi', ['Seyyid Vehbi', 'Nabi', 'Koca Ragıp Paşa'], 'Maraşlı olması, Tuhfe ve Nuhbe sözlükleri ile Lutfiyye Sünbülzade Vehbi\'yi gösterir.'),
  ('Divan şairlerine çağdaşlarınca verilen lakaplardan hangisi doğru kişiye bağlanmıştır?', 'Lamii Çelebi – Cami-i Rum', ['Nefi – Sultanü\'ş-şuara', 'Baki – Kasidenin sultanı', 'Nedim – Hikemi şiirin kurucusu'], 'Lamii\'ye Cami-i Rum denir; sultanü\'ş-şuara Baki\'nin, kasidenin sultanı Nefi\'nin unvanıdır, hikemi şiir ise Nabi ile anılır.'),
  ('Bağlı oldukları tasavvuf yolu bakımından hangi şair doğru nitelendirilmiştir?', 'Şeyh Galip – Mevlevilik', ['Lamii Çelebi – Bektaşilik', 'Neşati – Hurufilik', 'Nesimi – Nakşibendilik'], 'Şeyh Galip ve Neşati Mevlevi, Lamii Nakşibendi, Nesimi Hurufidir.'),
  ('Aşağıdaki şair-doğum yeri eşleştirmelerinden hangisi yanlıştır?', 'Nefi – Urfa', ['Baki – İstanbul', 'Zati – Balıkesir', 'Sünbülzade Vehbi – Maraş'], 'Nefi Erzurum\'un Hasankale kasabasında doğmuştur; Urfa Nabi\'nin doğum yeridir.'),
  ('Bir öğrenci Fuzuli, Baki, Nefi ve Nedim\'i \'yaşadıkları dönemin padişahı\' bakımından eşleştiriyor. Hangisi doğru bir eşleştirmedir?', 'Nedim – III. Ahmed', ['Fuzuli – IV. Murad', 'Nefi – Fatih Sultan Mehmed', 'Baki – III. Selim'], 'Nedim III. Ahmed\'in Lale Devri\'nde yaşamıştır; Fuzuli ve Baki Kanuni, Nefi IV. Murad dönemlerinin şairleridir.'),
  ('\'Kaside\' sözcüğünün Arapçadaki \'kasd\' kökünden gelmesi bu nazım şeklinin hangi özelliğiyle ilişkilendirilir?', 'Belli bir amaçla yazılması', ['Kısa ve özlü olması', 'Bentlerden oluşması', 'Bestelenmeye ve sazla okunmaya uygun olması'], 'Kasd \'niyet etmek, amaçlamak\' demektir; kaside birini övmek gibi belirli bir amaçla yazılan şiirdir.'),
  ('\'Gazel\' sözcüğünün Arapçadaki sözlük anlamı hangisidir?', 'Kadınlarla aşk üzerine konuşmak', ['Savaşta kahramanlık göstermek', 'Ölünün ardından ağlamak', 'Allah\'ı birlemek ve övmek'], 'Gazel sözlükte kadınlara aşk sözleri söylemek, onlarla sevgi üzerine konuşmak anlamına gelir; bu da türün aşk konusuyla örtüşür.'),
  ('\'Kıta\' sözcüğü \'parça\' anlamına gelir. Bu adın verilmesinin en makul açıklaması hangisidir?', 'Matlaı olmadığı için gazelden koparılmış bir parçaya benzemesi', ['Her zaman bir mesnevinin içinden alınması', 'Yalnız tek bir dizeden oluşması', 'Şairin divanını parçalara bölmesi'], 'Kıtada ilk beyit kafiyesizdir; bu yüzden matlaı atılmış bir gazel parçası gibi görünür.'),
  ('Kasidelerde şairin mahlası en çok hangi bölümlerde kullanılır?', 'Fahriye ya da dua', ['Nesibin ilk beytinde ve tecdid-i matlada', 'Girizgâh beytinde ve methiyenin başında', 'Kasidenin her beytinde ayrı ayrı'], 'Şair mahlasını genellikle kendini övdüğü fahriyede ya da kasideyi kapattığı dua bölümünde anar.'),
  ('Terkib-i bentte hanelerin kendi içindeki kafiye düzeni hangi nazım şeklininkine benzer?', 'Gazel', ['Mesnevi', 'Rubai', 'Tuyuğ'], 'Haneler, ilk beyti kafiyeli ve sonraki beyitlerin ikinci dizeleri bu kafiyeye uyan gazel düzeniyle yazılır.'),
  ('Murabbanın ilk bendi \'aaaa\' biçiminde kafiyelenmişse ikinci bendin kafiye düzeni genellikle nasıl olur?', 'bbba', ['abab', 'bbbb', 'bbab ccab'], 'Murabbada sonraki bentlerin ilk üç dizesi kendi arasında, son dizesi ilk bentle kafiyelenir.'),
  ('Şehrengizler Divan edebiyatında çoğunlukla hangi nazım şekliyle yazılmıştır?', 'Mesnevi', ['Tuyuğ', 'Rubai', 'Şarkı'], 'Bir şehrin güzellerini sırayla anlatan şehrengizler genellikle mesnevi biçiminde kaleme alınmıştır; Mesihi\'nin Edirne şehrengizi de mesnevidir.'),
  ('Müstezat adının \'artırılmış\' anlamına gelmesi neye dayanır?', 'Uzun dizelere kısa dizeler eklenmesine', ['Bent sayısının sürekli artmasına', 'Kafiyenin her beyitte çoğalmasına', 'Şiirin her okunuşta uzamasına'], 'Müstezatta her uzun dizenin ardından ziyade denen kısa bir dize eklenir; ad bu eklemeden gelir.'),
  ('Divan şairleri mersiyelerini en çok hangi nazım şekilleriyle yazmışlardır?', 'Terkib-i bent ve kaside', ['Tuyuğ ve rubai', 'Şarkı ve müstezat', 'Kıta, müfred ve tuyuğ'], 'Uzun ve yoğun duyguları anlatmaya elverişli olduğu için mersiyelerde çoğunlukla terkib-i bent ve kaside tercih edilmiştir.'),
  ('Bir şair, başka bir şairin ünlü bir beytini kendi şiirine olduğu gibi alıp kaynağını belli ederek kullanıyor. Divan şiirinde bu uygulamaya ne ad verilir?', 'Tazmin', ['Tahmis', 'Nazire', 'Tesdis'], 'Tazmin, başkasının dizesini ya da beytini şiirin içinde anarak kullanmaktır; tahmis ise beyitlere dize ekleyip bent kurmaktır.'),
  ('Divan şiirinde Hz. İsa\'nın göğe yükseltilip güneşin bulunduğu dördüncü kat gökte kaldığı inancı hangi mazmuna kaynaklık eder?', 'Güneşle komşuluk ve yücelik', ['Su altında yaşamak', 'Çölde kaybolmak', 'Zindanda kalmak'], 'Hz. İsa\'nın dördüncü kat gökte güneşle birlikte olduğu düşünülür; bu inanç yücelik ve güneşle ilgili benzetmelere yol açar.'),
  ('Divan şiirinde âşığın başını koyup beklediği, sevgilinin kapısının önündeki \'eşik\' hangi sözcükle anılır?', 'Asitan', ['Kûy', 'Bezm', 'Gülşen'], 'Asitan eşik demektir; âşık sevgilinin eşiğine yüz sürmeyi en büyük mutluluk sayar.'),
  ('Divan şiirinde sevgilinin saçının \'zincir\' olarak anılması âşıkla ilgili hangi durumu çağrıştırır?', 'Âşığın aşktan deliye dönüp zincire vurulması', ['Âşığın zengin olması', 'Âşığın hapisten kurtulması', 'Âşığın yolculuğa çıkması'], 'Eski çağlarda deliler zincire vurulurdu; aşktan divane olan âşığın sevgilinin saçına bağlanması bu yüzden zincirle anlatılır.'),
  ('Bir beyitte şair, sevgilinin boyunun (kamet) insanların üzerinde kıyamet koparttığını söylüyor. Bu söyleyişte hangi sözcük oyununa dayanılır?', 'Kamet ile kıyamet arasındaki ses ve kök yakınlığı', ['Gül ile bülbül arasındaki zıtlık', 'Mum ile pervane arasındaki benzerlik', 'Saç ile gece arasındaki renk benzerliği'], 'Kamet (boy) ve kıyamet aynı kökten gelir; şairler boyun güzelliğinin ortalığı birbirine kattığını bu ses benzerliğiyle anlatır.'),
  ('\'Mef\'ûlü fâilâtü mefâîlü fâilün\' kalıbıyla yazılmış bir dize kaç heceden oluşur?', '14', ['13', '15', '16'], 'Mef\'ûlü 3, fâilâtü 4, mefâîlü 4, fâilün 3 hecedir: toplam 14.'),
  ('Divan şairleri arasında ilmiye sınıfından (kadı, müderris, şeyhülislam) gelen şairlere örnek olarak hangisi verilebilir?', 'Baki', ['Zati', 'Taşlıcalı Yahya', 'Şeyh Galip'], 'Baki müderrislik ve kazaskerlik yapmıştır; Zati esnaf, Yahya asker, Şeyh Galip tekke şeyhidir.'),
  ('Divan şairleri arasında esnaflıkla geçimini sağlayan bir şaire örnek hangisidir?', 'Zati', ['Baki', 'Nabi', 'Nefi'], 'Zati çizmecilik ve remilcilikle geçinmiştir; ötekiler devlet ve ilmiye görevlerinde bulunmuştur.'),
  ('Divan şairlerinin farklı meslek gruplarından gelmesi (ilmiye, kalemiye, askerî sınıf, esnaf, tekke) Divan edebiyatıyla ilgili hangi yargıyı destekler?', 'Şiirin yalnız sarayla sınırlı kalmadığını', ['Divan şiirinin yalnız padişahlarca yazıldığını', 'Şairlerin hiçbir meslek sahibi olmadığını', 'Şiirin yalnız tekkelerde yazıldığını'], 'Şairler farklı toplumsal kesimlerden gelmiş; şiir saray kadar medrese, kalem odası, tekke ve çarşıda da yaşamıştır.'),
  ('Divan şairlerinden hangisi devlet kalemlerinde kâtiplik yaparak yetişip sonradan sadrazamlığa yükselmiştir?', 'Koca Ragıp Paşa', ['Şeyh Galip', 'Fuzuli', 'Zati'], 'Ragıp Paşa kalemiyeden yetişmiş, valilikler yapmış ve III. Mustafa\'nın sadrazamı olmuştur.'),
  ('Divan şiirinde meyhaneleri denetleyip şarap içilmesini yasaklayan ve bu yüzden rintlerin hoşlanmadığı görevli kimdir?', 'Muhtesib', ['Saki', 'Mugbeçe', 'Pir-i mugan'], 'Muhtesib çarşı ve ahlak düzenini denetleyen görevlidir; şiirde şarap küplerini kıran, rindin karşısındaki kişidir.'),
  ('Divan şiirinde âşığa aşkından vazgeçmesini öğütleyen ve âşığın kulak asmadığı kişiye ne ad verilir?', 'Nasih', ['Rakip', 'Saki', 'Muhtesib'], 'Nasih öğüt veren kişidir; âşık onun aşkı bırak öğüdünü dinlemez.'),
  ('Divan şiirinde camide öğüt verip insanları şaraptan ve dünya zevklerinden sakındıran, bu yüzden zahitle birlikte eleştirilen tip hangisidir?', 'Vaiz', ['Saki', 'Rint', 'Mugbeçe'], 'Vaiz kürsüden öğüt veren kişidir; şairler onun sözleriyle davranışları arasındaki çelişkiyi sık sık alaya alır.'),
  ('Divan şiirinde meyhanede şarap sunan genç, \'Mecusi çocuğu\' anlamındaki hangi sözcükle anılır?', 'Mugbeçe', ['Muhtesib', 'Nasih', 'Zahit'], 'Mugbeçe, Mecusi meyhanecinin çırağıdır; şarap sunan güzel genç olarak anılır.'),
  ('Divan şiirinde sevgilinin saçının kokusu için sık kullanılan \'misk-i Hoten\' ifadesindeki Hoten neyle ünlüdür?', 'Misk veren ceylanlarıyla', ['Altın madenleriyle', 'İnci avcılığıyla', 'Kılıç ustalarıyla'], 'Hoten, Orta Asya\'da misk ceylanlarıyla ünlü bir yerdir; saçın kokusu buradan gelen miske benzetilir.'),
  ('Divan şiirinde dudak için kullanılan \'la\'l-i Bedahşan\' ifadesinde Bedahşan neyle tanınır?', 'Değerli kırmızı taşlarıyla', ['Misk ceylanlarıyla', 'Güzel atlarıyla', 'Gül bahçeleriyle'], 'Bedahşan la\'l denen kırmızı değerli taşın çıkarıldığı yer olarak bilinir.'),
  ('Divan şiirinde Leyla ile Mecnun\'un hikâyesinin geçtiği çöl olarak anılan yer hangisidir?', 'Necd', ['Bisütun', 'Kenan', 'Hoten'], 'Necd Arap yarımadasında bir bölgedir; Mecnun\'un dolaştığı çöl olarak şiirde sık anılır.'),
  ('Divan şiirinde Ferhat\'ın Şirin için delmeye çalıştığı dağın adı nedir?', 'Bisütun', ['Kaf', 'Tur', 'Necd'], 'Ferhat\'ın dağı Bisütun\'dur; Tur Hz. Musa\'nın, Kaf Anka\'nın dağıdır.'),
  ('Divan şiirinde Hz. Yakup\'un yaşadığı ve oğlu Yusuf\'un hasretini çektiği yer olarak anılan ülke hangisidir?', 'Kenan', ['Mısır', 'Necd', 'Bedahşan'], 'Kenan ülkesi Yakup\'un yurdudur; Yusuf\'un satılıp götürüldüğü yer ise Mısır\'dır.'),
  ('Divan şiirinde âşığın ayrılık gecesinin uzunluğunu anlatmak için kullanılan \'şeb-i yelda\' neyi ifade eder?', 'Yılın en uzun gecesini', ['Ramazanın ilk gecesini', 'Kadir gecesini', 'Bayram arifesini'], 'Şeb-i yelda kış gündönümündeki en uzun gecedir; ayrılık gecesi de âşığa bu kadar uzun gelir.'),
  ('Divan şiirinde \'hazan\' mevsimi âşık ve dünya açısından çoğunlukla neyi simgeler?', 'Ayrılık, solgunluk ve geçiciliği', ['Kavuşma ve sevinci', 'Gençlik ve tazeliği', 'Bolluk ve zenginliği'], 'Hazan sonbahardır; yaprakların dökülmesi ayrılığı, ihtiyarlığı ve dünyanın geçiciliğini çağrıştırır.'),
  ('Divan şiirinde sevgilinin küçük ağzı Arap alfabesindeki hangi harfe benzetilir?', 'Mim', ['Elif', 'Dal', 'Lam'], 'Mim harfinin küçük yuvarlak başı dar ve küçük ağzı anlatmak için kullanılır.'),
  ('Divan şiirinde sevgilinin kıvrık saç lülesi biçimi bakımından hangi harfe benzetilir?', 'Lam', ['Elif', 'Mim', 'Ayın'], 'Lam harfinin kıvrık biçimi zülfü anlatmak için kullanılır.'),
  ('Divan şiirinde \'mescit\' ile \'meyhane\' çoğu zaman karşıt iki mekân olarak anılır. Bu karşıtlık hangi iki tipin dünyasını temsil eder?', 'Zahit ve rint', ['Saki ve mugbeçe', 'Âşık ve sevgili', 'Padişah ve vezir'], 'Mescit kuralcı zahidin, meyhane ise gönül ehli rindin mekânıdır; şairler çoğu zaman meyhaneden yana çıkar.'),
  ('Divan şiirinde kavuşma anı, ayrılık gecesinin karşıtı olarak hangi zaman dilimiyle anılır?', 'Sabah', ['Öğle sıcağı', 'İkindi vakti', 'Gece yarısı'], 'Ayrılık gecesi (şeb-i hicran) uzun ve karanlıktır; kavuşma ise aydınlık bir sabah gibi düşünülür.'),
  ('Enderunlu Vasıf ve Enderunlu Fazıl\'ın adlarında geçen \'Enderun\' neyi ifade eder?', 'Saraydaki eğitim kurumunu', ['Bir Anadolu kasabasını', 'Bir tarikatı', 'Bir şiir türünü'], 'Enderun, Topkapı Sarayı\'nda devlet adamı ve sanatçı yetiştiren saray okuludur; bu şairler orada yetişmiştir.'),
  ('Divan şiirinde Mevlevihanelerin edebiyat ve kültür hayatındaki önemi en iyi hangi örnekle açıklanabilir?', 'Şeyh Galip, Neşati ve Esrar Dede gibi şairlerin bu çevrelerde yetişmesi', ['Bütün kasidelerin burada yazılması zorunluluğu', 'Tezkirelerin yalnız burada saklanması', 'Aruzun bu kurumlarda yasaklanması'], 'Mevlevihaneler şiir ve musikinin geliştiği merkezlerdi; birçok önemli şair Mevlevi çevrelerinde yetişti.'),
  ('15. yüzyılın başında Bursa\'nın edebî bir merkez olduğunu gösteren en güçlü kanıt hangisidir?', 'Mevlid\'in burada bir cami imamınca yazılması', ['Hüsn ü Aşk\'ın burada yazılması', 'Nedim\'in burada yaşaması', 'Lale Devri eğlencelerinin burada yapılması'], 'Süleyman Çelebi Mevlid\'i Bursa\'da, Ulu Cami imamıyken yazmıştır; Bursa erken Osmanlı döneminin başkentiydi.'),
  ('Divan şiirinin Anadolu dışında da Çağatay, Azerbaycan, Kıpçak gibi sahalarda gelişmesi neyi gösterir?', 'Aruzlu klasik Türk şiirinin geniş bir coğrafyada ortak olduğunu', ['Bu şiirin yalnız İstanbul\'a özgü olduğunu', 'Türk lehçeleri arasında hiç etkileşim olmadığını', 'Bu sahalarda yalnız hece ölçüsünün kullanıldığını'], 'Nevai, Fuzuli, Nesimi, Seyf-i Sarayi gibi şairler aynı klasik geleneği farklı sahalarda sürdürmüştür.'),
  ('Süleyman Çelebi\'nin Mevlid\'inde Hz. Muhammed\'in doğumunu anlatan ve en çok okunan bölüm hangi adla bilinir?', 'Veladet Bahri', ['Miraç Bahri', 'Vefat Bahri', 'Münacat Bahri'], 'Mevlid bahir denen bölümlere ayrılır; doğumun anlatıldığı Veladet Bahri en tanınmış bölümdür.'),
  ('Hz. Muhammed\'in vasıflarını anlatan hilye metinlerinin hattatlarca levha biçiminde yazılmasına standart düzeni veren 17. yüzyıl hattatı kimdir?', 'Hafız Osman', ['Şeyh Hamdullah', 'Mustafa Rakım', 'Ahmed Karahisari'], 'Hafız Osman, hilyeyi göbek, hilal ve köşelerden oluşan levha düzenine kavuşturmuştur.'),
  ('Revani, Riyazi ve Nevizade Atai\'nin ortak olarak yazdığı eser türü hangisidir?', 'Sakiname', ['Surname', 'Şehrengiz', 'Hilye'], 'Revani\'nin İşretname\'si, Riyazi\'nin ve Atai\'nin sakinameleri bu türün tanınmış örnekleridir.'),
  ('Hoca Dehhani\'nin Selçuklu tarihini konu alan ve Farsça yazdığı rivayet edilen eseri hangi türdendir?', 'Şehname', ['Hilye', 'Tezkire', 'Sakiname'], 'Dehhani\'nin Selçukluların tarihini Farsça bir şehname biçiminde yazdığı aktarılır; eser günümüze ulaşmamıştır.'),
  ('Yedi beyitlik bir gazelde kafiyeye giren dizelerin toplam sayısı kaçtır?', '8', ['7', '14', '6'], 'Matla beytinin iki dizesi ile diğer altı beytin ikinci dizeleri kafiyelidir: 2 + 6 = 8.'),
  ('Her hanesi 6 beyit olan 5 bentlik bir terci-i bentte, aynen tekrarlanan vasıta beyitleri bir kez sayılırsa kaç farklı beyit bulunur?', '31', ['35', '30', '36'], 'Haneler 5 × 6 = 30 farklı beyit eder; tekrarlanan vasıta beyti 1 farklı beyittir: 30 + 1 = 31.'),
  ('Divan şiirinde sevgilinin gözü, Arapçada \'göz\' anlamına da gelen hangi harfle anılır?', 'Ayın', ['Elif', 'Mim', 'Dal'], 'Ayın (ayn) harfi hem harf adı hem de \'göz\' demektir; şairler bu çift anlamdan yararlanır.'),
  ('Azmizade Haleti\'nin ustalaştığı dörtlük biçimi için söylenenlerden hangisi doğru değildir?', 'Türklerin icat ettiği bir nazım şeklidir', ['Dört dizeden oluşur', 'Felsefi ve tasavvufi düşünceleri işlemeye elverişlidir', 'Ahreb ve ahrem kalıplarıyla yazılır'], 'Rubai Fars edebiyatından gelmiştir; Türklerin icadı olan dörtlük tuyuğdur.'),
  ('Baki\'nin Kanuni için yazdığı uzun ağıtın biçimi olan terkib-i bent anlatılırken bir öğrenci dört yargı ileri sürüyor. Bunlardan hangisi hatalıdır?', 'Vasıta beyti bütün bentlerde aynıdır', ['Bentler hane ve vasıtadan oluşur', 'Mersiye yazmakta sık kullanılmıştır', 'Hanelerin beyitleri gazel gibi kafiyelenir'], 'Vasıta beytinin değişmeden tekrarlanması terci-i bendin özelliğidir; terkib-i bentte her bendin vasıtası farklıdır.'),
  ('Aşağıdaki şairlerden hangisi 18. yüzyıl mahallileşme akımının temsilcileri arasında sayılmaz?', 'Şeyh Galip', ['Nedim', 'Enderunlu Fazıl', 'Bosnalı Sabit'], 'Şeyh Galip kapalı ve girift Sebk-i Hindi üslubunu sürdürmüştür; ötekiler yerli hayatı ve konuşma dilini şiire taşımıştır.'),
  ('Divan şiirinde hüdhüd kuşunun Hz. Süleyman\'a haberini getirdiği Saba ülkesinin melikesi kimdir?', 'Belkıs', ['Züleyha', 'Şirin', 'Leyla'], 'Hüdhüd Saba melikesi Belkıs\'tan haber getirmiş; bu kıssa şiirde haberci kuş mazmununa kaynaklık etmiştir.'),
  ('Bir şair padişaha sunduğu küçük armağanı mazur göstermek için karıncanın Hz. Süleyman\'a çekirge budu armağan etmesini anıyor. Bu telmihle şair ne demek istemektedir?', 'Armağanın değerinin büyüklüğünde değil, gönülden verilmesinde olduğunu', ['Padişahın karıncalar kadar çok askeri olduğunu', 'Kendi şiirinin padişahınkinden üstün olduğunu', 'Armağanını geri istediğini'], 'Karıncanın küçük armağanı Süleyman tarafından kabul edilmiştir; şair de mütevazı hediyesinin hoş görülmesini diler.'),
  ('Divan ve mecmua gibi yazma eserleri elle kopyalayan kişiye ne ad verilir?', 'Müstensih', ['Müellif', 'Mütercim', 'Musahhih'], 'Müstensih eseri istinsah eden, yani kopyalayan kişidir; eserin yazarı ise müelliftir.'),
  ('Divan şiirinde \'ebrû\' sözcüğü neyi ifade eder?', 'Kaşı', ['Yanağı', 'Dudağı', 'Boyu'], 'Ebrû Farsçada kaş demektir; \'ebrû-yı yâr\' sevgilinin kaşıdır.'),
  ('Divan şiirinde \'dehen\' sözcüğü hangi anlamda kullanılır?', 'Ağız', ['Göz', 'Boyun', 'Alın'], 'Dehen ağız demektir; küçüklüğü nedeniyle nokta ya da mim harfine benzetilir.'),
  ('Divan şiirinde \'çeşm-i mest\' tamlaması nasıl bir göz anlatır?', 'Sarhoş, baygın bakışlı göz', ['Ağlayan göz', 'Kör göz', 'Uykusuz göz'], 'Mest sarhoş demektir; sevgilinin süzgün ve baygın bakışlı gözü bu tamlamayla anlatılır.'),
  ('Mevlana\'nın Mesnevi\'si kaç ciltten (defterden) oluşur?', '6', ['4', '5', '7'], 'Mesnevi altı defterden oluşur; Mevlevi geleneğinde \'Mesnevi-i Şerif\' diye anılır.'),
  ('Usuli ve Hayali gibi şairlerin dünyadan el etek çekmeyi, ilahi aşkı ve vahdeti işleyen gazelleri hangi gazel türüne girer?', 'Sufiyane gazel', ['Şuhane gazel', 'Rindane gazel', 'Hikemi (öğretici) gazel'], 'Tasavvufi düşünceleri işleyen gazellere sufiyane (tasavvufi) gazel denir.'),
  ('Divan edebiyatında kadın şairlerin sayıca az olmasının en makul açıklaması hangisidir?', 'Medrese eğitimine ve şiir meclislerine katılma olanaklarının sınırlı olması', ['Kadınların aruz bilmemesinin yasak olması', 'Kadın şairlerin yalnız hece ölçüsünü kullanması', 'Tezkirecilerin kadın adı yazmasının yasaklanması'], 'Şiir eğitimi medrese ve meclis çevrelerinde yürüdüğü için kadınların bu çevrelere erişimi sınırlıydı; buna karşın Mihri, Zeynep, Fıtnat gibi şairler yetişti.'),
  ('Divan şiirinin tarihi dönemlere ayrılırken Dehhani\'den Ahmet Paşa\'ya uzanan 13-15. yüzyıllar için en çok hangi nitelendirme kullanılır?', 'Kuruluş dönemi', ['Klasik dönem', 'Mahallileşme dönemi', 'Son dönem'], 'Divan şiirinin Anadolu\'da kök saldığı, kurallarının ve ustalarının oluştuğu 13-15. yüzyıllar kuruluş dönemi sayılır.'),
  ('Kasidelerde padişahın adaletinin, cömertliğinin ve fetihlerinin sürekli övülmesi Divan şiirinin hangi işlevini gösterir?', 'Hükümdarın meşruiyetini ve gücünü yüceltme işlevini', ['Halkı isyana çağırma işlevini', 'Ticaret anlaşmalarını kaydetme işlevini', 'Aruz kurallarını öğretme işlevini'], 'Methiyeler, sarayın gücünü ve hükümdarın değerini dile getirerek devlet ideolojisini de yansıtır.'),
  ('Divan şiirinde âşığın sevgili uğruna canını vermeye hazır olması, babasının kurban etmek istediği hangi peygamberin kıssasıyla anılır?', 'Hz. İsmail', ['Hz. Yakup', 'Hz. Yunus', 'Hz. Eyüp'], 'Hz. İbrahim\'in oğlu İsmail\'i kurban etmeye hazırlanması, teslimiyet ve fedakârlığın simgesi olarak anılır.'),
  ('\'Nefi\' mahlası sözlükte hangi anlamı taşır?', 'Faydalı', ['Kederli', 'Uzak', 'Gizli ve saklı'], 'Nef \'fayda\' demektir; Nefi \'faydalı\' anlamındadır.'),
  ('Necati divanını hangi padişaha sunarak onun ilgisini kazanmıştır?', 'II. Bayezid', ['Fatih Sultan Mehmed', 'Yavuz Sultan Selim', 'Kanuni Sultan Süleyman'], 'Necati\'nin şiirleri II. Bayezid\'in beğenisini kazanmış ve onun himayesine girmiştir.'),
  ('Nefi kasidelerini sırasıyla hangi padişahlara sunmuştur?', 'I. Ahmed, II. Osman, IV. Murad', ['Fatih, II. Bayezid, Yavuz', 'Kanuni, II. Selim, III. Murad', 'III. Ahmed, I. Mahmud, III. Osman'], 'Nefi 17. yüzyılın ilk yarısında I. Ahmed, II. Osman ve IV. Murad\'a kasideler sunmuştur.'),
  ('Leyla ile Mecnun hikâyesinde Mecnun\'un mensup olduğu Arap kabilesi hangisidir?', 'Beni Amir', ['Beni Mahabbet', 'Beni Ümeyye', 'Beni Haşim'], 'Kays, Beni Amir kabilesindendir; Beni Mahabbet ise Hüsn ü Aşk\'taki hayalî kabiledir.'),
  ('Divan şiirinde bülbül için kullanılan ve \'bin\' anlamına da gelen Farsça sözcük hangisidir?', 'Hezâr', ['Hümâ', 'Kumru', 'Sîmürg'], 'Hezâr hem \'bin\' hem de bülbül demektir; şairler bülbülün bin türlü nağmesini bu ikili anlamla anar.'),
  ('Divan şiirinde sevgilinin yüzündeki beni anlatmak için kullanılan sözcük hangisidir?', 'Hâl', ['Hat', 'Ruh', 'Leb-i la\'l'], 'Hâl ben demektir; hat ayva tüyü, ruh yanak, leb dudaktır.'),
  ('Şeyh Galip\'in naatındaki \'kûy-i Mahbub-ı Hüda\'dır bu\' ve \'makam-ı Mustafa\'dır bu\' dize sonlarında redif ve kafiye nasıl ayrılır?', 'Redif \'-dır bu\', kafiye \'a\' sesi', ['Redif \'bu\', kafiye \'-dır\'', 'Redif \'Hüda\', kafiye \'Mustafa\'', 'Redif yok, kafiye \'-dır bu\''], 'Dize sonlarında aynen tekrarlanan \'-dır bu\' rediftir; ondan önceki Hüda/Mustafa sözcüklerindeki \'a\' sesi kafiyedir.'),
  ('Rubai ile kıtayı ayıran özellik aşağıdakilerden hangisidir?', 'Rubainin belirli aruz kalıplarıyla yazılması', ['Kıtanın her zaman tek beyit olması', 'Rubainin bentlerden oluşması', 'Kıtanın bestelenmek için yazılması'], 'Rubai ahreb-ahrem kalıplarına bağlıdır ve dört dizeyle sınırlıdır; kıta her kalıpla yazılabilir ve beyit sayısı ikiden fazla olabilir.'),
  ('Müstezatın yapısı en çok hangi nazım şeklinin her dizesine kısa bir ek dize eklenmiş biçimine benzetilir?', 'Gazel', ['Mesnevi', 'Tuyuğ', 'Murabba'], 'Müstezat, gazel düzeninde kafiyelenen uzun dizelere ziyadeler eklenerek oluşturulmuş bir biçimdir.'),
  ('Koca Ragıp Paşa hangi yüzyılın Divan şairidir?', '18. yüzyıl', ['16. yüzyıl', '17. yüzyıl', '15. yüzyılın ortası'], 'Ragıp Paşa 1699\'da doğmuş, 1763\'te sadrazamken ölmüştür; 18. yüzyıl hikemi şiirinin temsilcisidir.'),
  ('Aşağıdaki mesnevilerden hangisinin konusu eski bir Arap ya da İran hikâyesinden alınmamış, şairin kendi kurgusudur?', 'Hüsn ü Aşk', ['Leyla vü Mecnun', 'Hüsrev ü Şirin', 'Yusuf u Züleyha'], 'Leyla vü Mecnun Arap, Hüsrev ü Şirin İran, Yusuf u Züleyha Kur\'an kaynaklıdır; Hüsn ü Aşk ise Şeyh Galip\'in özgün kurgusudur.'),
  ('Divan şiirinde sevgilinin küçük ve kapalı ağzı hangi çiçek durumuna benzetilir?', 'Gonca', ['Solgun gül', 'Açmış lale', 'Kurumuş menekşe'], 'Gonca açılmamış gül tomurcuğudur; küçük ve kapalı ağız ona benzetilir, gülümseme de goncanın açılmasıdır.'),
  ('Divan şiirinde lalenin biçimi nedeniyle benzetildiği nesne hangisidir?', 'Kadeh', ['Kılıç', 'Kalem', 'Ayna'], 'Lalenin çanak biçimli çiçeği içi şarap dolu bir kadehe benzetilir.'),
  ('Divan şiirinde mumun erirken akan damlaları âşıkla ilişkilendirilerek nasıl yorumlanır?', 'Âşığın gözyaşları gibi', ['Sevgilinin gülüşü gibi', 'Rakibin hilesi gibi', 'Sakinin kadehe doldurduğu şarap gibi'], 'Eriyen mum, aşk ateşinde yanıp gözyaşı döken âşığa benzetilir.'),
  ('Divan şiirinde gazel ile şarkının dili karşılaştırıldığında şarkı için genellikle hangisi söylenir?', 'Daha sade ve konuşma diline yakındır', ['Daha ağır ve Arapça yüklüdür', 'Hiç Türkçe sözcük içermez', 'Yalnız Farsça yazılır ve hiç bestelenmez'], 'Bestelenmek için yazılan şarkılar, özellikle Nedim\'den sonra, daha sade ve akıcı bir dille kaleme alınmıştır.'),
  ('Divan şiirinde \'mihr\' sözcüğünün hem \'güneş\' hem de başka bir anlam taşıması şairlere söz oyunu imkânı verir. Bu ikinci anlam hangisidir?', 'Sevgi', ['Gece', 'Gözyaşı', 'Toprak'], 'Mihr Farsçada hem güneş hem sevgi, şefkat demektir; şairler sevgilinin yüzü ile sevgisini bu ikili anlamla birlikte anar.'),
  ('Divan şiirinde \'ebr\' sözcüğü hangi doğa unsurunu anlatır ve âşıkla ilişkisi genellikle nasıl kurulur?', 'Bulut; âşığın ağlayan gözü gibi yağmur döker', ['Rüzgâr; sevgilinin haberini getirir', 'Deniz; sevgilinin derin gözlerini anlatır', 'Dağ; rakibin katılığını anlatır'], 'Ebr buluttur; âşığın gözü yağmur döken buluta benzetilir.'),
  ('Divan şiirinde \'nigâr\' sözcüğü hangi iki anlamı birlikte taşıdığı için şairlerin sevdiği bir sözcüktür?', 'Sevgili ve resim', ['Kadeh ve şarap', 'Bahçe ve gül', 'Kılıç ve savaş kalkanı'], 'Nigâr hem sevgili hem de resim, nakış anlamına gelir; sevgilinin resim gibi güzelliğini çağrıştırır.'),
  ('Divan şiirinde yanak anlamındaki \'ruhsâr\' ile eş anlamlı olarak kullanılan sözcük hangisidir?', 'Ârız', ['Zülf', 'Müjgân', 'Gerdan'], 'Ârız da ruhsâr gibi yanak demektir; zülf saç, müjgân kirpik, gerdan boyundur.'),
  ('Divan şiirinde Hızır\'ın bastığı yerin yeşerdiği inancı hangi mazmuna kaynaklık eder?', 'Hızır\'ın yeşillik ve bereketle anılması', ['Hızır\'ın çöl ve kuraklıkla anılması', 'Hızır\'ın denizde boğulması', 'Hızır\'ın dağları delerek yol açması'], 'Hızır\'ın uğradığı yerin yeşillendiğine inanılır; bu yüzden yeşil renk ve bahar onunla ilişkilendirilir.'),
  ('Divan şiirinde \'Ayna-yı İskender\' mazmunu hangi efsaneye dayanır?', 'İskender\'in uzakları gösteren dev bir ayna yaptırması', ['İskender\'in aynada kendi ölümünü görmesi', 'İskender\'in ayna satıcısı olması', 'İskender\'in aynayı denize atması'], 'İskenderiye\'de uzaktaki gemileri gösteren bir ayna yapıldığı anlatılır; şiirde gönül ve kadeh bu aynaya benzetilir.'),
  ('Divan şiirinde Hz. Süleyman\'ın tahtının neyle taşındığına inanılır?', 'Rüzgârla', ['Fillerle', 'Gemilerle', 'Develerle'], 'Süleyman\'ın rüzgâra hükmettiği ve tahtının rüzgârla taşındığı anlatılır.'),
  ('Leyla adının Arapçada \'gece\' anlamındaki \'leyl\' sözcüğüyle ilgisi şairlerce hangi güzellik unsuruyla ilişkilendirilir?', 'Kara saç', ['Beyaz yüz', 'Kırmızı dudak', 'Uzun boy'], 'Leyla adı geceyi çağrıştırır; şairler bunu siyah saç ve karanlık gecelerle birlikte kullanır.'),
  ('\'Şirin\' adının Farsçadaki \'tatlı\' anlamı Divan şiirinde en çok hangi unsurla birlikte söz oyununa konu olur?', 'Şeker ve şerbet', ['Kılıç ve kalkan', 'Deniz ve gemi', 'Kar, buz ve kış soğuğu'], 'Şirin tatlı demektir; şairler bu adı şeker, bal ve dudak tatlılığıyla birlikte anarak söz oyunları yapar.'),
  ('Hüsrev ü Şirin hikâyesinde Ferhat\'ın Şirin için dağdan kazdığı ark hangi sıvıyı taşımak içindir?', 'Süt', ['Şarap', 'Bal', 'Gül suyu'], 'Nizami\'nin anlatımında Ferhat, Şirin\'in sarayına sürülerden süt ulaştırmak için dağdan ark kazar.'),
  ('Hüsrev ü Şirin hikâyesinde Hüsrev\'in ünlü atının adı nedir?', 'Şebdiz', ['Düldül', 'Burak', 'Rahş'], 'Şebdiz Hüsrev\'in kara atıdır; Rahş Rüstem\'in, Düldül Hz. Ali\'nin bineğidir.'),
  ('Ferhat ile Mecnun Divan şiirinde aşkın iki farklı yüzünü temsil eder. Bu farkı en iyi açıklayan hangisidir?', 'Ferhat emek ve çabayı, Mecnun kendinden geçişi simgeler', ['Ferhat zenginliği, Mecnun yoksulluğu simgeler', 'Ferhat zahidi, Mecnun rakibi simgeler', 'İkisi de sevgiliye kavuşup mutlu olur'], 'Ferhat dağ delerek aşkını emekle kanıtlar; Mecnun ise aklını yitirip çöllere düşerek aşkta kendinden geçmeyi temsil eder.'),
  ('Divan şiirinde bir şairin başka bir şairin şiirine nazire yazması işine ne ad verilir?', 'Tanzir', ['Tahmis', 'Tazmin', 'Tesdis'], 'Nazire yazmaya tanzir denir; ortaya çıkan şiir nazire adını alır.'),
  ('Kafiye bilgisinde kafiyenin dayandığı, her beyitte tekrarlanması zorunlu olan asıl harfe ne ad verilir?', 'Revi', ['Redif', 'Ziyade', 'Vasıta'], 'Revi kafiyenin temel harfidir; redif ise ondan sonra gelen ve aynen tekrarlanan ek ya da sözcüklerdir.'),
  ('Sünbülzade Vehbi\'nin öğüt mesnevisine Lutfiyye adını vermesinin nedeni hangisidir?', 'Eseri oğlu Lutfullah için yazması', ['Eseri Lutfi Paşa\'ya sunması', 'Eserin Mevlana Lutfi\'ye nazire olması', 'Eserin Lutf adlı bir şehirde yazılması'], 'Sünbülzade Vehbi öğütlerini oğlu Lutfullah\'a yönelttiği için eserine Lutfiyye adını vermiştir.'),
  ('Keçecizade İzzet Molla\'nın mesnevisine adını veren Keşan, şairin hayatında hangi anlamı taşır?', 'Sürgün edildiği yer', ['Doğduğu kasaba', 'Kadılık yaptığı şehir', 'Mevlevi şeyhi olduğu yer'], 'İzzet Molla II. Mahmud döneminde Keşan\'a sürgün edilmiş, bu dönemin sıkıntılarını mesnevisinde anlatmıştır.'),
  ('Şeyh Galip yaklaşık kaç yaşında ölmüştür?', '42', ['26', '63', '81'], '1757\'de doğan Şeyh Galip 1799\'da, kırk iki yaşında ölmüştür.'),
  ('Divanlarda bina, doğum, ölüm gibi olaylar için yazılmış tarih manzumeleri genellikle nasıl yer alır?', 'Ayrı bir \'Tarihler\' bölümünde toplanır', ['Divanın en başına, dibaceden önce konur', 'Gazellerin içine dağıtılır', 'Divana hiç alınmaz'], 'Divan tertibinde tarih manzumeleri çoğunlukla kasidelerden sonra \'Tarihler (Tevarih)\' başlığı altında toplanır.'),
];
